programs.haiku:
"""Local-area words. The component fires on words for a local, rural or regional place
(local, region, county, village, valley, island, mountain, river, province, and the
Chinese equivalents 当地 地方 地区 县 村 乡 镇 山 野 平原 沿海), and on 'of' right after such
a word ("the western part of", "Republic of"). It is mildly positive on general place and
land words (area, state, land, people) and slightly negative on 'of' in quantity phrases
("a wide range of") and on the reasoning tags <think> and </think>."""
READS = ()

STRONG = {
    " local", "local", " Local", "/local", " locally", "当地", "地方", "地区", "地區", "野",
    " administrative", " province", " Province", " provincial", " county", " County",
    " district", " District", " Municip", " municipality", " rural", " village", " villages",
    "村", "村级", "乡", "镇", "古镇", "县", "縣", "省", " island", " islands", " Island",
    " peninsula", " Peninsula", " river", " River", " valley", " Valley", " valleys",
    " Mountains", " mountains", " mountain", "山", "平原", "沿海", " coastal", " coast", " Coast",
    " inland", " Highlands", " Highland", " Hill", " western", " Western", " northern",
    " southern", " eastern", " southeastern", " tribal", " remote",
}
WEAK = {
    " region", " regions", " land", " lands", " place", " places", " located", " people",
    " border", " bay", " lake", " town", " Republic", " territory", " territorial",
    " regional", " Region", " area", " areas", " state", " State", " states", " States",
    "地", "州", "域", "湿地", "景区",
}
PLACE = STRONG | WEAK
QUANTITY = {" range", " amount", " degree", " degrees", " number", " variety", " lot", " top",
            " surface", " choice", " selection", " wide", " large", " array", " total"}
TAGS = {"<think>", "</think>"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in STRONG:
        return None, 1.15
    if tok in WEAK:
        return None, 0.45
    if tok == " of":
        if prev in PLACE:
            return None, 0.3
        if prev in QUANTITY:
            return None, -0.25
        return None, 0.0
    if tok in TAGS:
        return None, -0.3
    return None, 0.0

"""Layer-0 MLP down_proj component 3777, a word-class detector (rough version).

Reads only the current token's text and the previous token's text, and predicts
the component's activation from their word classes:
  - a whole content word (a space-led alphabetic word that is not a function word)
    pushes the activation up, most when the previous token is also a content word
    (the second word of a compound such as "base line" or "military police");
  - function words, digits and punctuation sit slightly below zero.
"""

READS = ()

FUNCTION_WORDS = set(
    "the of and a an to in is that for with on as by at from it this be are was or "
    "not but which he she they we you i its their his her there has have had been "
    "were will can would".split()
)


def word_class(token):
    s = token.strip()
    if s == "":
        return "space"
    if s.isdigit():
        return "digit"
    if s.lower() in FUNCTION_WORDS:
        return "function"
    if all(ch.isalpha() for ch in s):
        return "content" if token.startswith(" ") else "subword"
    if all(not ch.isalnum() for ch in s):
        return "punct"
    return "mixed"


CUR = {"content": 0.07, "subword": 0.0, "mixed": 0.13, "function": -0.05,
       "digit": -0.06, "punct": -0.05, "space": -0.03}
PREV = {"content": 0.07, "subword": 0.01, "mixed": -0.03, "function": -0.03,
        "digit": 0.0, "punct": -0.02, "space": 0.02}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    value = 0.02 + CUR[word_class(cur)] + (PREV[word_class(prev)] if prev else 0.0)
    return carry, float(value)

programs.sol:
"""A token-level detector for the word family 'object'.

The complete English word is strongest; plurals, obj abbreviations, identifier
compounds, and translations are weaker cues. Case and attached punctuation
modify the estimate. Entity/instance/subject/self receive smaller responses.
The following 'of' can fire. 象 responds weakly alone, more strongly when it
completes a Chinese/Japanese object word. End-of-text responds separately.
Other tokens are predicted zero; one-token context resets at document boundaries.
This recognizes spellings, not referents or object-oriented program structure.
"""
from string import punctuation

READS = ()
OBJECT_TRANSLATIONS = {
    '对象': 5.8, 'объект': 3.5, 'objeto': 3.5, 'objetos': 3.0,
    'objet': 2.0, '物件': 2.7, '객체': 4.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip(punctuation)
    lower = word.lower()
    value = 0.0
    if token == '<|endoftext|>':
        value = 1.055
    elif lower == 'object':
        value = 6.8 if word == 'Object' else 6.0
        if token[:1] in ('.', '-', '/') and word == 'object':
            value = 7.4
        elif token[:1] in ('(', '<'):
            value -= 1.3
    elif lower == 'objects':
        value = 4.7 if token == ' objects' else 5.7
    elif lower == 'obj':
        value = 2.5 if token[:1] in ('(', ')') else 3.5
    elif lower in ('objective', 'objectively', 'objectives', 'objection', 'objections'):
        value = 1.0
    elif lower == 'objected':
        value = 2.2
    elif 'object' in lower:
        value = 2.7 if 'Object' in word else 1.7
    elif word in OBJECT_TRANSLATIONS:
        value = OBJECT_TRANSLATIONS[word]
    elif word.endswith('对象'):
        value = 5.8
    elif lower in ('entity', 'entities', 'instance', 'instances', 'instanceof', 'subject'):
        value = 0.8
    elif lower in ('subjects', 'subjected'):
        value = 0.57
    elif lower == 'self':
        value = 0.3
    elif previous in ('object', 'objects') and token == ' of':
        value = 1.7
    elif word == 'tượng':
        value = 3.1 if previous == 'đối' else 1.0
    elif word == 'đối':
        value = 0.83
    elif token == '象':
        # Decode together: Japanese 対 may be split into invalid UTF-8 pieces.
        tail = prefix.text_prefixes[-1][-2:] if previous else token
        value = {'对象': 8.0, '對象': 6.8, '対象': 2.9}.get(tail, 1.0)
    return (doc, lower), float(value)

programs.luna:
"""Recognize object-related words and the end of a packed document."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.casefold()
    if token == "<|endoftext|>":
        return None, 1.05
    if "objective" in word:
        return None, 1.2
    if "object" in word or "对象" in word or "objeto" in word:
        return None, 5.6
    if "instance" in word:
        return None, 0.85
    if "entity" in word:
        return None, 0.8
    if "subject" in word:
        return None, 0.8
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down-projection component layers.0.mlp.down_proj:3779 (Qwen3-1.7B).

What it does, in plain terms: this component has no single concept. Its activation is a
small, signed, token-specific signal (std about 0.03; most values within +-0.1) spread
across the whole vocabulary. Coarse token classes (digits, CJK, punctuation, words with or
without a leading space) all average to about zero, and no simple rule explains much of it.

This program predicts only the few responses that can be named:
  * the document header "<|endoftext|>Title:": the token "Title" right after a document
    break is about +0.33, and the colon after it is about -0.31;
  * chat/reasoning markup "<tool_call>" and "</think>": about +0.09;
  * chat turn and tool closers "<|im_end|>" and "</tool_call>": about -0.04;
  * the place names " York", " London" and " Moscow": about -0.13.
Everywhere else it predicts 0.

Main program: `step` reads only the newest token and the one or two before it.
"""

READS = ()

DOC_BREAK = "<|endoftext|>"
TITLE_HEADER_VALUE = {"Title": 0.33}
TITLE_COLON_VALUE = -0.31
MARKUP_OPEN = {"<tool_call>", "</think>"}
CHAT_CLOSE = {"<|im_end|>", "</tool_call>"}
PLACE_NAMES = {" York", " London", " Moscow"}

MARKUP_VALUE = 0.09
CHAT_CLOSE_VALUE = -0.04
PLACE_VALUE = -0.13


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    now = tokens[-1]
    before = tokens[-2] if len(tokens) > 1 else ""
    before2 = tokens[-3] if len(tokens) > 2 else ""

    if before2 == DOC_BREAK and before == "Title" and now == ":":
        value = TITLE_COLON_VALUE
    elif before == DOC_BREAK and now in TITLE_HEADER_VALUE:
        value = TITLE_HEADER_VALUE[now]
    elif now in MARKUP_OPEN:
        value = MARKUP_VALUE
    elif now in CHAT_CLOSE:
        value = CHAT_CLOSE_VALUE
    elif now in PLACE_NAMES:
        value = PLACE_VALUE
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Predict a few first-person suggestion tokens and document-opening markers."""
READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    previous = tokens[-2] if len(tokens) > 1 else ""
    previous = previous.strip().lower()

    # First-person openings: "let me", "let's", and "let us".
    if previous == "let":
        word = token.strip().lower()
        if word == "me":
            return None, 1.115
        if token.strip() in ("'s", "’s"):
            return None, 1.416
        if word == "us":
            return None, 0.965

    # Some headings and code markers immediately after an end-of-text marker.
    if len(tokens) > 1 and tokens[-2] == "<|endoftext|>":
        values = {
            "#": -1.292,
            "//": -1.119,
            "<?": -1.379,
            "--": -0.886,
            "#pragma": -0.739,
            "function": -0.335,
            "const": -0.220,
            "string": -0.125,
        }
        return None, values.get(token, 0.0)
    return None, 0.0

programs.sol:
"""Negative lexical detector centered on 台/臺 and 'platform'.

台 means a platform/stage, is a counter for machines, and occurs in Taiwan
names. Its compounds activate less strongly than the character alone.
Table, Mac, console, forum and TV words are weaker associated triggers.
A few compound phrases soften the response; unlisted tokens return zero.
It recognizes token spellings, not every mention of these concepts; this
is not a claim that all these uses have the same meaning.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip().strip('_@./-<(')
    word = bare.lower()
    value = 0.0
    same_doc = len(prefix.token_ids) > 1 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = prefix.token_strings[-2].strip().lower() if same_doc else ''

    # Recover a character completed by a separate UTF-8 byte token.
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith(('台', '臺')):
        value = -9.1
    elif bare in {'台', '臺'}:
        value = -8.4 if bare == '臺' else -8.1
        if same_doc and bare == '台':
            ending = prefix.text_prefixes[-1]
            if ending.endswith('控制台'):
                value = -4.35
            elif ending.endswith(('洗手台', '收银台', '收銀台',
                                  '工作台', '写字台', '觀景台', '观景台')):
                value = -6.5
            elif previous.isdigit():
                value = -6.8
    elif (len(bare) == 2 and bare[-1] == '台'
          and bare[0] in '一二三四五六七八九十百千万'):
        value = -4.1 if bare[0] == '万' else -6.5
    elif bare in {'台上', '台下'}:
        value = -6.0
    elif bare in {'平台', '平台上', '舞台', '舞台上', '后台', '前台'}:
        value = -3.5
    elif bare in {'台湾', '台灣', '臺灣', '台北', '台南', '台中'}:
        value = -2.5
    elif bare in {'电视台', '電視台', '电台', '電台', '出台'}:
        value = -2.2
    elif '台' in bare or '臺' in bare:
        unrelated_senses = {'台词', '台詞', '台阶', '台階', '台风', '台風', '茅台'}
        value = -0.7 if bare in unrelated_senses else -1.5
    elif word in {'platform', 'platforms'}:
        value = -3.1 if word == 'platform' else -2.7
        if previous in {'social', 'media'}:
            value = -2.7
    elif word in {'plataforma', 'plataformas', 'plateforme', 'plateformes'}:
        value = -1.3
    elif word in {'table', 'tables'}:
        value = -1.25 if word == 'tables' else -0.85
        if bare == 'TABLE':
            value = -0.6
        elif previous in {'periodic', 'conversion', 'lookup'}:
            value = -0.55
    elif word == 'mac':
        value = -1.5 if bare == 'Mac' else -1.2
        if token == 'mac' or bare == 'MAC':
            value = -0.75
    elif word in {'macbook', 'macos'}:
        value = -0.7
    elif word in {'console', 'consoles'}:
        value = -0.45 if bare == 'Console' else -0.7
    elif word in {'forum', 'forums'}:
        value = -0.9
    elif word in {'television', 'televisions'}:
        value = -0.65
    elif word in {'tv', 'tvs'}:
        value = -0.28
    elif word in {'desk', 'desks', 'desktop', 'tablet', 'tablets'}:
        value = -0.42
    elif word in {'computers', 'machines', 'portable'}:
        value = -0.6
    elif word in {'audience', 'stage', 'station', 'theater', 'theatre',
                  'arena', 'podium'}:
        value = -0.3
    elif word == 'markets':
        value = -0.7
    elif word in {'taiwan', 'taipei', 'mainland'}:
        value = -1.0
    elif '桌' in bare:
        value = -1.5
    elif bare in {'论坛', '論壇', '坛', '壇'}:
        value = -1.25
    elif bare in {'場', '场', '市场', '市場', '架', '柜', '대'}:
        value = -0.6
    elif bare in {'电视', '電視', 'テレビ'}:
        value = -0.6
    elif (word == 'of'
          and previous in {'table', 'tables', 'platform', 'platforms'}):
        value = -0.4 if previous == 'table' else -0.55
    return None, value

programs.haiku:
"""Platform / table / computer-and-screen / forum word detector.

Component layers.0.mlp.down_proj:3784 is a token-level feature. Its activation is strongly
negative on words for a platform or stage, moderately negative on words for a table, a Mac or
game console, TV, a forum or a market, and near zero elsewhere. The program reads only the
current token and returns a fixed value for each word class:

  platform (any form, English or 平台/舞台/台湾)  about -3   (the bare character 台 or 臺, the
                                                              Chinese for platform, stage or
                                                              Taiwan's station: about -8)
  table, tables, desk, 桌                         about -0.9
  Mac                                             about -1.4
  console, television, TV, tablet, machines       about -0.6
  forum, markets, 市场, 场, 場                     about -0.7
  anything else                                   0
"""

import re

READS = ()

BARE_PLATFORM = set("台臺")                      # the character by itself
TABLE = {"table", "tables", "desk", "桌", "桌子"}
MAC = {"mac", "macos", "macbook"}
DEVICE = {"console", "consoles", "television", "tv", "tablet", "tablets", "machines", "monitor"}
VENUE = {"forum", "forums", "markets", "市场", "市場", "场", "場"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    word = re.sub(r"[^a-z]", "", s.lower())      # " table", "_table", "(Table" -> "table"
    if s in BARE_PLATFORM:
        value = -8.0
    elif "platform" in word or any(c in s for c in "台臺") or "平台" in s or "舞台" in s:
        value = -3.0
    elif word in MAC:
        value = -1.4
    elif word in TABLE or s in TABLE:
        value = -0.9
    elif word in DEVICE:
        value = -0.6
    elif word in VENUE or s in VENUE:
        value = -0.7
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate a sparse negative cue for venues, interfaces, and devices.

In sampled contexts the clearest examples are platform, table, market, and
console; the same cue also appears on a few related words and translations.
This small word-class rule ignores sentence context and predicts nothing else.
"""

READS = ()

RELATED_WORDS = frozenset({
    "market", "markets", "市场", "市場", "console", "television",
    "forum", "desk", "court", "人民法院", "place", "场", "場所",
    "場", "portal", "портал", "library", "mac", "forum",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if "平台" in word or word == "platform":
        return None, -3.2 if word in {"平台", "platform"} else -1.0
    if word in {"table", "@table"}:
        return None, -0.95
    if word in {"mac", "_mac"}:
        return None, -1.2
    if word in {"/library", "library"}:
        return None, -0.6
    if word in RELATED_WORDS:
        return None, -0.7
    return None, 0.0

programs.sol:
"""Approximate a negative boundary-marker response.

The main triggers are punctuation tokens introduced by a space, especially
colons and question marks. The preceding token's alphabetic length, case,
and leading space set their strength; indentation and symbols are weaker
contexts. Most spaced punctuation gets an early-document boost.
Lowercase spaced 'which' is weaker after commas or prepositions than after
words, while 'shall' is negative. Dot/bang runs are handled separately.
Unlisted tokens predict zero, omitting smaller lexical responses.
"""
from math import exp

READS = ()
PREPOSITIONS = frozenset('in of for to at on from by through with upon under '
                        'during after over without about into among within '
                        'before between beyond against via as'.split())
LINKERS = frozenset('and or that but'.split())
# Negative magnitudes after indentation, symbols, numbers/letters, full words.
MARKS = {
    ':': (1.1, 1.6, 1.7, 2.65),
    '?': (1.1, 1.4, 1.9, 2.65),
    ',': (0.2, 0.5, 0.77, 1.4),
    ';': (0.5, 1.25, 1.45, 1.95),
    '.': (0.0, 0.2, 0.43, 0.82),
    ')': (0.3, 0.7, 0.92, 1.4),
    ']': (0.1, 0.4, 0.4, 0.75),
    '!': (0.35, 0.7, 1.0, 1.8),
    '/': (-0.15, 0.0, 0.14, 0.37),
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == doc else 0
    carry = (doc, position)
    token = prefix.token_strings[-1]
    prev = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        prev = prefix.token_strings[-2]
    word = token.strip()
    p = prev.strip()
    if word.lower() == 'shall':
        return carry, -0.66 if token == ' shall' else -0.33
    if token == ' which':
        if not p or p.endswith(',') or p in PREPOSITIONS:
            value = -0.08
        elif p in LINKERS:
            value = -0.17
        elif prev[-1].isalpha():
            value = -0.68 if len(p) > 2 else -0.38
        else:
            value = -0.32 if prev[-1].isdigit() or p[-1] in ')]}\'"”’`' else -0.1
        return carry, value
    if word and set(word) == {'.'}:
        if len(word) == 2:
            return carry, -0.95 if token.startswith(' ') else -0.54
        if len(word) == 4:
            return carry, -0.53
        if len(word) >= 3:
            return carry, -0.08 if token.startswith(' ') else 0.14
    if word and set(word) <= {'!', '！'} and len(word) >= 2:
        return carry, -1.05 if token.startswith(' ') else -0.64
    if not token.startswith(' ') or not word or word[0] not in MARKS:
        return carry, 0.0
    mark, tail = word[0], word[1:]
    if tail and any(c not in ',.;:?!)-\'"' for c in tail):
        return carry, 0.0
    if mark == ':' and tail.startswith(':'):
        return carry, -0.25
    if mark == '.' and prev == ' .':
        return carry, 0.05
    indent, symbol, short, whole = MARKS[mark]
    if not p:
        magnitude = indent
    elif prev[-1].isalpha():
        if p.isascii():
            fraction = min(1.0, (len(p) - 1) / 4.0)
            if not prev.startswith(' '):
                fraction *= 0.65
            magnitude = short + fraction * (whole - short)
            if mark == ':' and len(p) > 2 and p.istitle():
                magnitude += 0.6
        else:
            magnitude = short
    elif prev[-1].isdigit() or p[-1] in ')]}\'"”’`':
        magnitude = short
    else:
        magnitude = symbol
    if tail:
        magnitude *= 0.35 if mark == ')' else 0.65
    if '\n' in token:
        magnitude *= 0.7 if mark == ')' else 0.85 if mark == '?' else 1.0
    if position == 0:
        magnitude *= 0.25
    elif mark != '/':
        gain = 0.15 if mark in '?!' else 0.3
        magnitude *= 0.94 + gain * exp(-position / 64.0)
    return carry, -magnitude

programs.haiku:
"""Negative on words of knowing, thinking, hearing, noticing and confusion, and strongly
negative at the end of a document (<|endoftext|>).

Three strengths of the cognition words, and the word before modulates them: after "you", a
negation, a modal or "ever/never" a verb is stronger; after "I" or "we" ("I think") weaker.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"

# Knowing, not knowing, forgetting, wondering, confusion, familiarity; Chinese 知道, 不知道...
STRONG = {"know", "knew", "knows", "knowing", "heard", "forget", "forgot", "wonder", "wondered",
          "wondering", "wonders", "confused", "confusing", "confusion", "confuse", "aware",
          "misunderstood", "unfamiliar", "imagined", "知道", "不知道", "不知", "都知道", "以为",
          "忘了", "忘记", "错过", "误解", "混淆", "疑惑", "怀疑", "明白", "听说过", "想想", "问"}
# Thinking, believing, hearing, noticing, asking, telling, doubt; Chinese 想, 认为, 觉得...
MILD = {"think", "thought", "thinking", "believe", "seen", "understand", "understood",
        "understanding", "misunderstanding", "sure", "ask", "asked", "asking", "asks", "tell",
        "telling", "realize", "realized", "realise", "notice", "noticed", "remember", "expect",
        "expecting", "doubt", "sorry", "worry", "guess", "guessing", "questions", "interested",
        "familiar", "surprise", "surprised", "hear", "hearing", "hears", "imagine", "afraid",
        "wish", "想", "认为", "觉得", "发现", "注意", "了解", "看到", "听"}
# Weaker cognition words
WEAK = {"known", "believed", "believes", "told", "assume", "assumed", "expected", "question",
        "see", "seeing", "what", "about", "want", "wanted", "hope", "attention", "looking"}
# A word before the verb that makes it stronger or weaker
BEFORE_STRONGER = {"you", "not", "never", "ever", "no", "any", "may", "might", "would", "will",
                   "could", "should", "can", "t", "have", "been", "always", "even"}
BEFORE_WEAKER = {"i", "we"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token == END_OF_TEXT:
        return None, -1.3
    if word in STRONG:
        value = -1.0
    elif word in MILD:
        value = -0.4
    elif word in WEAK:
