"""A past-reference detector, strongest on passive verbs and past-time words.

Past forms of 'be' give strong cues; present forms and reduced-clause
markers ('as', 'when') give weaker ones. Participles, naming/reporting
verbs, ability, and temporal adverbs respond to that cue. Adverbs may intervene. A small response continues
onto the 'by' or 'to' following a predicted past description.
"""
READS = ()

PAST_DESCRIPTION = set('''
    found shown thought born named described reported created published
    established introduced declared discovered observed identified proposed
    suggested proved proven verified
'''.split())
EVENT_PARTICIPLES = set('''
    released recorded appointed announced demonstrated designed developed
    calculated determined obtained added asked constructed founded launched
    awarded elected
'''.split())
IRREGULAR_PARTICIPLES = set('''
    made written given seen told built sent said held sold chosen bought
    won heard brought lost drawn caught understood read met kept paid taught
'''.split())
PAST_TIME = {'previously', 'recently', 'originally', 'once'}
TIME_MODIFIERS = {'first', 'last', 'later', 'earlier', 'formerly', 'initially'}
WEAK_PARTICIPLES = set('''
    used done taken known put set carried treated collected edited based
    associated left broken
'''.split())
NOT_PAST = {'red', 'bed', 'hundred', 'need', 'speed', 'indeed', 'feed', 'seed'}
CUES = {
    'was': 1., 'were': .72, 'been': .74, 'being': .30,
    'is': .12, 'are': .12, 'be': .12, 'am': .12,
    'had': .15, 'have': .02, 'has': .02, 'as': .12, 'when': .3,
}


