    """Ordinary response and sensitivity to a grammatical cue."""
    if word in PAST_DESCRIPTION:
        return -0.120, 2.54
    if word in EVENT_PARTICIPLES:
        return -0.043, 1.88
    if word in PAST_TIME:
        return -0.242, 2.95
    if word in TIME_MODIFIERS:
        return -0.021, 1.65
    if word == 'able':
        return 0.022, 2.43
    if word in {'unable', 'likely', 'supposed'}:
        return -0.099, 1.32
    if word in {'wondering', 'hoping'}:
        return -0.365, 2.98
    if word in WEAK_PARTICIPLES:
        return 0.045, 0.81
    if word in IRREGULAR_PARTICIPLES:
        return 0.039, 1.35
    if word in {'ed', 'ated', 'ized', 'ised', 'ified'}:
        return -0.023, 0.10
    if word.isalpha() and word.endswith('ed') and word not in NOT_PAST:
        return 0.057, 0.97
    if word == 'to':
        return 0.005, 0.76
    if word == 'by':
        return 0.032, 0.42
    if word in {'in', 'of'}:
        return -0.001, 0.13
    if word.isalpha() and word.endswith('ing'):
        return 0.010, 0.15
    return 0.000, 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0., 0., 0.)
    _, recent_auxiliary, modifier_cue, previous_response = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    baseline, sensitivity = response(word)
    value = baseline - sensitivity * (recent_auxiliary + modifier_cue)
    if word in {'by', 'to'}:
        value += .27 * min(previous_response, 0.)
    # Retain a weaker cue across modifiers, determiners, or word pieces.
    modifier = (word.endswith('ly') or word in TIME_MODIFIERS
                or word in {'not', 'just', 'also', 'then', 'never',
                            'already', 'only', 'soon'})
    if modifier:
        auxiliary = .6 * recent_auxiliary
    elif word in {'the', 'a', 'an', 'my', 'his', 'her', 'their', 'our'}:
        auxiliary = .25 * recent_auxiliary
    elif not token[:1].isspace() and word.isalpha():
        auxiliary = .4 * recent_auxiliary
    else:
        auxiliary = 0.
    auxiliary += CUES.get(word, 0.)
    cue = .4 if word in {'previously', 'recently', 'originally'} else 0.
    if word in {'first', 'last', 'later', 'earlier'}:
        cue = .2
    return (doc, auxiliary, cue, value), float(value)

