"""A local approximation, mostly for unspaced East Asian text.

A two-character Han token gets a negative response after one Han character;
common grammatical characters weaken or reverse that response. Hiragana
adjective-like and -る endings also tend negative, especially after one kanji.
Small English word classes and the Go ']string' spelling have separate values.

Only the previous token is remembered. These are coarse training-derived rules,
not a parser: they miss substantial word-specific variation. A larger Chinese
word-overlap lexicon improved activation fit slightly but not output KL.
"""
READS = ()

LINKS = frozenset('的和与與及或在从從是把')
GRAMMAR = frozenset(
    '我你您他她它这這那其有用会會能要想被将將由等着著'
    '得了使于於為为以已来來到给給向去也就但而且让讓還'
    '还對对'
)
MODIFIERS = frozenset(
    '一二三四五六七八九十百千万億亿大小多少总總太高长'
    '長新老上下前后後每自非不更可'
)

# Ordinary grammatical/semantic word classes, matched without case or spacing.
ENGLISH = (
    # Reflexive pronouns.
    (frozenset('myself yourself himself herself itself ourselves yourselves '
               'themselves oneself'.split()), 0.080),
    # Alternatives.
    (frozenset('other another alternative alternatives else '
               'otherwise'.split()), 0.041),
    # Concessive/contrast markers.
    (frozenset('although though however despite nevertheless notwithstanding '
               'whereas'.split()), 0.050),
    # Minimum and maximum terminology.
    (frozenset('least minimal minimum'.split()), 0.095),
    (frozenset('maximum maximal'.split()), 0.043),
    # Completeness adverbs.
    (frozenset('completely entirely fully totally'.split()), -0.086),
