    if han(token):
        if len(token) == 2:
            if single_han:
                if previous in LINKS:
                    value = 0.05
                elif previous in GRAMMAR:
                    value = -0.04
                elif previous in MODIFIERS:
                    value = -0.28
                else:
                    value = -0.25
            else:
                value = -0.025 if previous_han else 0.012
        elif len(token) == 1:
            if single_han:
                value = 0.02
            else:
                value = -0.02 if previous_han else 0.01
        else:
            value = -0.01
