        if len(token) == 1:
            value = 0.01
        elif len(token) == 2:
            if token in {'しい', 'しく', 'そう', 'ない'}:
                value = -0.26 if single_han else -0.14
            elif token.endswith('る') and token not in {'する', 'ある', 'いる'}:
                value = -0.23 if single_han else -0.10
            elif single_han:
                value = -0.10
            else:
                value = -0.065 if hiragana(previous) else -0.03
        else:
            value = -0.013
    elif token == ']string':
        value = -0.53
    else:
        word = token.strip().lower()
        for words, response in ENGLISH:
            if word in words:
                value = response
