import math
import unicodedata

READS = ()
MARKERS = {
    '-': .91, '--': 1.25, '---': 2.05, '+': .88,
    '*': .77, '**': .78, '|': 1.50, '>': 1.65,
    '#': .53, '##': .32, '###': .21, '####': .35,
    '#####': .50, '######': .70, '#[': .96,
    '//': 1.20, '///': 2.35, '/*': 1.05, '/**': 1.35,
    '{"': 1.18, '@@': 1.07, '=': .39, '===': 1.12,
    '`': 1.02, '``': .62, '```': .62,
    '!': 1.40, '~~': 1.30, '.': .83, '...': 1.75,
    ':': .76, '}': .76, '[': .24, '\\': .33, '\xa0': 1.20,
    '•': .67, '・': .86, '—': .80, '–': .55,
}


def marker_size(body, spaced):
    if spaced and body in ('*', '//', '///'):
        return {'*': 1.55, '//': 1.15, '///': 1.65}[body]
    if body in MARKERS:
        return MARKERS[body]
    if body.startswith('<') and body.endswith('>'):
        return 0.0
    if any(ch.isalnum() for ch in body):
        return {'/': .32, '#': .25, '.': .08}.get(body[0], 0.0)
    if body[0] in '()\ufffd':
        return 0.0
    if len(set(body)) == 1 and len(body) > 1:
        return {'-': 1.25, '#': .9, '/': 1.1, '=': .7,
                '_': 1.0, '|': 1.5, '>': 1.65}.get(body[0], .7)
    if body[0] in '●○◆◇■□▲△▼▽★☆※✓✔✅☑':
        return .75
    return .5 if unicodedata.category(body[0])[0] in 'PS' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, fresh, gaps, indent, previous_break = 0, False, 0, 0, ''
    else:
        _, pos, fresh, gaps, indent, previous_break = carry
    token = prefix.token_strings[-1]
    body = token.lstrip(' \t').rstrip('\r\n')
    spaced = token.startswith((' ', '\t'))
    normalized = token.replace('\r\n', '\n').replace('\r', '\n')
    breaks = normalized.count('\n')
    value = 0.0
    if fresh and body:
        amount = marker_size(body, spaced)
        blank_lines = previous_break.count('\n')
        if blank_lines >= 2:
            amount *= 1.5 if body == '•' else 1.2 + .1 * min(2, blank_lines - 2)
        ending = previous_break.rstrip('\n').strip(' \t')
        if ending.endswith(('.', '?', '。')):
            amount *= .85
        if ending.startswith(('/*', '*')) and body.startswith('*'):
            amount *= 1.4
        if ending.endswith('|') and body.startswith('|'):
            amount *= 1.3
        amount *= .55 ** gaps * math.exp(-max(0, indent - 3) / 25)
        value = -amount * (.3 if breaks else 1.0)
    elif body.startswith('//') and pos:
        if body.startswith('///'):
            value = -.46 if spaced else -.68
        else:
            value = -.15 if spaced else -.24
    if breaks:
        if breaks >= 2:
            size, decay = (1.45, 1.0) if body else (1.85, 1.4)
            value += size / (pos + 1) ** decay
        elif pos < 4:
            value += (.32 if body else .71) * math.exp(-1.5 * pos)
    if token == '<|endoftext|>':
        value = 1.69 if not pos else .9 / math.sqrt(pos + 1) - .06
    if not pos and body and body[:1] in '-/|#' and not any(ch.isalnum() for ch in body):
        scale = .15 if body in ('#', '/') or spaced else .6
        value = -scale * marker_size(body, spaced)
    if breaks:
        tail = normalized.rsplit('\n', 1)[1]
        fresh, gaps, indent = not tail.strip(' \t'), 0, len(tail)
        previous_break = normalized
    elif token.strip(' \t'):
        fresh = False
    elif fresh:
        gaps += 1
        indent += len(token)
    return (doc, pos + 1, fresh, gaps, indent, previous_break), value

