FILL_RUNS = {"....": -2.0, " ....": -2.0, "\xa0\xa0\xa0\xa0": -1.4, " \xa0 \xa0": -1.2}


def _value(s):
    if s in FILL_RUNS:
        return FILL_RUNS[s]
    if s and set(s) == {" "}:
        n = len(s)
        if n == 4:
            return -1.5
        if n % 4 == 0:
            return -0.8
        if n in (5, 6):
            return -0.6
        if n >= 11 and n % 4 == 3:
            return 0.25
        return 0.0
    if s.startswith("\t") and s.count("\t") == 1 and 1 <= len(s) - 1 <= 5 and set(s[1:]) == {" "}:
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    return None, float(_value(prefix.token_strings[-1]))

