"""layers.0.mlp.down_proj:3798 -- a "formal/mathematical predicate" detector.

This component goes negative on the word that links a subject to a predicate in
mathematical or formal writing: "is", "are", "be", "must", "necessarily", "implies",
"finite", "impossible", and the broken-up pieces of such words ("irre|ducible").
The more mathematical the surrounding document is (LaTeX, variables, digits), the more
negative it gets. A copula after a pronoun, "what", "who" or "there" stays near zero,
and it is most negative after a symbol or a variable ("$F$ is", "p(x) is").

The program keeps a running count of math-looking tokens in the current document. Its
prediction is minus a constant times that running fraction, with a size set by the kind
of word and by what precedes it. Everything else predicts 0.
"""

import re

READS = ()

LINKERS = {" is", " are", " be", " must"}
MATH_WORDS = {
    " necessarily", " implies", " impossible", " finite", " linear", " exist",
    " exists", " hold", " holds", " zero", " uniquely", " hence", " any",
    " non", " no", " every", " always", "ible", "itive", "irre", "-is", "ducible",
}
PRONOUNS = {
    "it", "this", "that", "which", "what", "who", "there", "he", "she", "they",
    "we", "you", "i", "here", "how", "where", "can", "will", "would", "could",
    "may", "should", "might",
}
MATH_SYMBOL_ENDS = (")", "$", "}", "]")


def _is_math_token(s):
    """A token that looks like mathematics: LaTeX/markup, a variable, a digit or a math word."""
    t = s.strip()
    if any(c in s for c in "$\\{}_^"):
        return True
    if re.fullmatch(r"[A-Za-z]", t) or re.fullmatch(r"\d+", t):
        return True
    return t.lower() in {"prove", "theorem", "equation", "integer", "matrix", "prime",
                         "lemma", "proof", "polynomial", "function", "field", "group"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    cur = tokens[t]
    new_doc = t == 0 or docs[t] != docs[t - 1]
    # carry = (count of math-looking tokens so far in this document, count of tokens so far)
    if carry is None or new_doc:
        n_math, n_tok = 0, 0
    else:
        n_math, n_tok = carry
    frac = (n_math + 0.5) / (n_tok + 2.0)   # math fraction of the document so far, before cur
    prev = tokens[t - 1] if t > 0 and not new_doc else ""
    prev_s = prev.strip()
    new_carry = (n_math + _is_math_token(cur), n_tok + 1)

    if cur in LINKERS:
        if prev_s.endswith(MATH_SYMBOL_ENDS) or prev_s.isdigit() or re.fullmatch(r"[A-Za-z]", prev_s):
            value = -(0.15 + 1.4 * frac)     # after a symbol, variable or number
        elif prev_s.lower() in PRONOUNS:
            value = -0.85 * frac             # "it is", "what is", "there is"
        else:
            value = -(0.05 + 1.1 * frac)
    elif cur in MATH_WORDS:
        value = -(0.03 + 1.0 * frac)
    else:
        value = 0.0
    return new_carry, float(value)

