"""A horizontal-spacing detector, strongest on three-space tokens.

Short runs of spaces are more negative within a line than just after a
newline, with small adjustments for preceding punctuation. For these short
runs the negativity is stronger near the beginning of a document. Longer
indentation, tabs, and nonbreaking spaces use separate length rules.
Ordinary text and newline-containing tokens are predicted as zero.
"""
READS = ()

# Length: (within a line, at a line boundary, early-document extra negativity).
SPACES = {
    2: (-1.09, 0.06, 0.30),
    3: (-3.27, -1.92, 1.08),
    4: (-1.40, -0.07, 0.41),
    5: (-0.93, -0.03, 0.33),
    6: (-0.23, 0.42, 0.14),
    7: (-1.05, -0.67, 0.42),
    8: (0.03, 0.59, 0.03),
}
AFTER_TAB = {1: -1.0, 2: -0.53, 3: -1.22, 4: -0.18, 5: 0.04}
NONBREAKING = {2: -0.5, 3: -2.18, 4: -0.85, 7: -0.81}


def preceding_punctuation(previous, line_start):
    p = previous.rstrip()
    c = p[-1:]
    if c and c in ';,':
        return 0.25 if line_start else 0.08
    if c and c in ')]}':
        return 0.16 if line_start else -0.12
    if c == ':':
        return -0.13 if line_start else -0.44
    if c and c in '*/#':
        return -0.21
    if not line_start and c.isdigit():
        return 0.24
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    s = prefix.token_strings[-1]
    line_start = position == 0 or previous.endswith(('\n', '\r'))
    value = 0.0
    if s and s.isspace() and '\n' not in s and '\r' not in s:
        n = len(s)
        if not s.strip(' '):
            if n in SPACES:
                inside, boundary, early = SPACES[n]
                value = (boundary if line_start else inside)
                value -= early * 40 / (position + 40)
            elif 9 <= n <= 19:
                if n % 4 == 3:
                    value = -0.62 + 0.23 * line_start
                elif n % 4 == 1:
                    value = -0.06 + 0.5 * line_start
                else:
                    value = 0.22 + 0.52 * line_start
            elif n >= 20:
                value = (-0.95 if n == 23 else -1.35) if n % 4 == 3 else -0.7
                value += (0.1 if n % 4 == 3 else 0.5) * line_start
            if n >= 2:
                scale = 1.0 if n == 3 else (0.6 if n <= 7 else 0.3)
                value += scale * preceding_punctuation(previous, line_start)
        elif '\xa0' in s:
            value = NONBREAKING.get(n, 0.0)
        elif not s.strip('\t'):
            if n == 1:
                value = -0.58 if line_start else -0.7
            elif n <= 4:
                value = 0.14 if n == 3 else 0.03
            else:
                value = max(-1.0, -0.2 * (n - 3))
        elif s.startswith('\t') and not s.lstrip('\t').strip(' '):
            n = len(s.lstrip('\t'))
            value = AFTER_TAB.get(n, 0.15)
            if n >= 7 and n % 4 == 3:
                value = -0.35 if n <= 15 else (-0.58 if n == 19 else -1.2)
    return (doc, position, s), float(value)

