    s = prefix.token_strings[-1]
    if not s or "\n" in s or not HORIZONTAL_SPACE.issuperset(s):
        return carry, 0.0
    if s in (" ", "\xa0"):
        return carry, 0.0
    if "\t" in s:
        return carry, -0.6
    if len(s) == 3:
        return carry, -2.2
    if len(s) == 2:
        return carry, -0.25
    return carry, -0.7

