"""Approximate the component's main positive six and negative ellipsis responses.

Recognize selected written forms of six, including split English number words
and June (month six). The digit response varies with the preceding token class.
Ellipses, including LaTeX horizontal dots, are negative; spaces and line endings
change their strength. Listed assurance/protection words are a separate positive
family, and the opening tool-response tag is negative. Use typical training
activation sizes, leaving other lexical variation at zero.
"""
READS = ()

# Related forms of the number six, with their typical response sizes.
SIX_FORMS = {
    '６': 0.78,
    '六': 1.09,       # six
    '第六': 1.09,     # sixth
    '十六': 0.86,     # sixteen
    '六十': 0.80,     # sixty
    'six': 0.80,
    '-six': 0.99,
    'sixth': 0.85,
    'sixty': 0.89,
    'sixteen': 0.65,
    'june': 0.37,
}


# Selected assurance/protection forms, separate from the number family.
ASSURANCE = {
    'guarantee': 0.42,
    'guarantees': 0.42,
    'guaranteed': 0.15,
    'protection': 0.22,
    '保障': 1.55,     # safeguard/assurance
    '保证': 0.40,     # guarantee, simplified Chinese
    '保證': 0.36,     # guarantee, traditional Chinese
    '保护': 0.38,     # protection, simplified Chinese
    '保護': 0.14,     # protection, traditional Chinese/Japanese
}


def ellipsis_response(token):
    """Distinguish spaced ellipses, bracketed omissions, and attached dots."""
    before, dots, after = token.partition('...')
    if not dots:
        before, dots, after = token.partition('…')
    if any(c in before for c in '([{'):
        return -0.70
    if token.startswith(' '):
        if dots == '…':
            return -0.54
        if token.count('.') > 3:
            return -0.30
        if not after:
            return -0.92
        if after.isspace():
            return -1.17 if after.count('\n') == 1 else -1.03
        return -0.64
    if dots == '…':
        return -0.06
    if token.count('.') != 3:
        return 0.0
    if before:
        return -0.27
    if after and not after.isspace():
        return -0.25
    return -0.25 if after.count('\n') == 1 else -0.12


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_document = len(prefix.token_ids) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    previous = prefix.token_strings[-2] if same_document else ''
    if previous.strip().lower() == 'six' and token in {
        'th', 'ty', 'teen', 'teenth'
    }:
        return None, 0.34 if token == 'th' else 0.47
    if token in {'ots', 'dots'}:
        start = max(0, len(prefix.token_ids) - 3)
        tail = ''.join(
            prefix.token_strings[i] for i in range(start, len(prefix.token_ids))
            if prefix.document_ids[i] == prefix.document_ids[-1]
        )
        if tail.endswith(('\\ldots', '\\cdots', '\\dots')):
            return None, -0.37
    if token == '6':
        if not same_document:
            value = 0.975
        elif previous and (previous[-1].isalpha() or previous[-1] == '_'):
            value = 0.98
        elif previous.isdigit():
            value = 0.813
        else:
            value = 0.76
    elif token == '<tool_response>':
        value = -0.307
    elif '...' in token or '…' in token:
        value = ellipsis_response(token)
    else:
        word = token.strip().lower()
        value = SIX_FORMS.get(word, ASSURANCE.get(word, 0.0))
    return None, value

