        if '\n' in s:
            value = 0.74 if new else -1.0 if prev == '<|im_end|>' else 0.01
        elif '\r' in s or '\x0c' in s:
            value = -0.85
        elif len(s) == 1 and s != '\t':
            value = 0.08 if direct else -0.045 if line else 0.004
        elif line:
            value = -0.32 if s in {'  ', '   '} else 0.06
        elif '\t' in s:
            value = -min(1.4, 0.44 + 0.04*s.count(' ') + 0.26*(s.count('\t')-1))
        elif '\xa0' in s:
            value = -0.10 * (len(s) - 1)
        else:
            value = -min(1.5, 0.35 + 0.05*len(s))
    # Explicit conversation and tool framing.
    elif s.startswith('<') and s.endswith('>'):
        if s == '<|im_start|>':
            value = 0.35 if new else -0.03
        elif s == '</think>':
            value = -0.89
        else:
            value = -0.05
    elif prev == '<|im_start|>':
        value = (-0.17 if initial else -0.60) if s == 'user' else 0.067
    # First nonblank text on a line: case, code, and punctuation classes.
    elif line and text:
        first = text[0]
        if s[0].isspace():
            if text.startswith(('//', '#')):
                value = -0.37
            else:
                value = (-0.43 if text in CODE_WORDS else
                         -0.22 if first.islower() else -0.09)
            if direct:
                value = -0.28
            elif '\t' in prev:
                value += 0.16
            elif len(prev) >= 4:
                value += 0.10
            else:
                value -= 0.12
        elif first.isdigit():
            value = -0.48 if direct else -0.02
        elif first.isalpha():
            value = -0.95 if first.isascii() and first.islower() else -0.69
        elif '\n' in s:
            value = -0.36
        elif s.startswith(('---', '===', '***')):
            value = -0.90
        elif first in '-*>':
            value = -0.18
        elif first in '#`[' or s.startswith('{"'):
            value = -0.80
        elif first == '.' and s[1:2].isalpha():
            value = -1.10
        elif first in '/+\\=':
            value = -0.90
        else:
            value = -0.40
    elif prev.endswith('\\n') and text and not s[0].isspace():
        value = -0.28
    if direct and opener == '<tool_response>' and text and not s.startswith('<'):
        value -= 0.48
    # Indentation keeps the pending line-start pulse armed.
    if text:
        opener = s
    if '\n' in s:
        line = not s.rsplit('\n', 1)[-1].strip()
    else:
        line = line and s.isspace()
    return (doc, s, line, new, opener), float(value)

programs.haiku:
"""Line-start detector (negative). Fires on the first word of a new line, and on indentation."""
import re

READS = ()

SPECIAL = re.compile(r"<[^>]*>")  # chat / control markers such as <|im_start|>


def _has_newline(s):
    return "\n" in s or "\r" in s


def _word_value(s):
    x = s.strip()
    if not x or SPECIAL.fullmatch(x):
        return 0.0
    if s.startswith(" "):
        return -0.25
    if x[0].isdigit():
        return -0.4
    if x[0].isalpha() and x[0].islower():
        return -0.9
    if x[0].isalpha():
        return -0.7
    return -0.5


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    if cur.strip() == "":
        if len(cur) < 2 or _has_newline(cur):
            return carry, 0.0
        return carry, (-0.2 if _has_newline(prev) else -0.6)
    if _has_newline(prev):
        return carry, _word_value(cur)
    return carry, 0.0

programs.luna:
"""Predict negative pulses for line openings and visible text layout.

Words at line starts are strongest; punctuation and numbers are weaker.
Runs of spaces and tabs also mark columns, while ordinary tokens stay near 0.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        seen_newline, blank_tail = False, True
    else:
        _, seen_newline, blank_tail = carry

    at_line_start = seen_newline and blank_tail
    word = token.strip()
    if "\t" in token and token.isspace():
        if at_line_start:
            value = 0.05
        elif len(token) == 1:
            value = -0.18
        else:
            value = -0.38
    elif "\t" in token:
        value = -0.23
    elif token.isspace() and "\n" not in token and len(token) > 1:
        value = -0.30
    elif at_line_start and word and word[0].isalpha():
        value = -0.76
    elif at_line_start and word and word[0].isdigit():
        value = -0.17
    elif at_line_start and word:
        value = -0.40
    elif at_line_start:
        value = -0.14
    else:
        value = -0.006

    if "\n" in token:
        blank_tail = not token.rsplit("\n", 1)[1].strip()
        seen_newline = True
    elif token:
        blank_tail = blank_tail and not token.strip()
    return (doc, seen_newline, blank_tail), float(value)

programs.sol:
"""Recognize raw/structured line starts, rather than ordinary prose.

The first token after a newline gets a negative response especially for
numbers, lowercase names, file names, and bare opening punctuation.
Capitalized prose and normal indentation have little response. Padded
blank lines also activate negatively. The next token gets a small tail.
These rules summarize recurring line-start patterns in the training data.
They use visible token forms and small word classes, not tokenizer IDs.
"""
import unicodedata

READS = ()

IMPORTS = set('import include require'.split())
DECLARATIONS = set('package namespace class def function func'.split())
TRANSFERS = set('return break continue goto yield'.split())
TYPES = set('int bool float double void long short char byte string'.split())
LOG_LABELS = set('test tests error warning debug trace'.split())
CONTROL_FLOW = set('if else elif for while do switch case try catch'.split())
MODIFIERS = set('public private protected static const let var using export'.split())
IDENTIFIERS = set('src dist bin lib root target build app pkg self client '
                  'context console index value data generator file time '
                  'total count number result expected actual day'.split())
REPOSITORY_FILES = ('LICENSE', 'README', 'CHANGELOG', 'CONTRIBUTING',
                    'CODE_OF_CONDUCT', 'Makefile', 'Dockerfile')

# Bare symbol, versus a token beginning with that symbol and containing more text.
PUNCTUATION = {
    '(': (-0.73, -0.27), '[': (-0.77, -0.19), '{': (-0.62, -0.39),
    '+': (-0.68, -0.13), '\\': (-0.81, -0.20),
    '"': (-0.26, 0.12), "'": (-0.26, 0.12), '“': (0.12, 0.12),
    '`': (-0.27, 0.14), '<': (-0.39, -0.16), '>': (-0.39, -0.16),
    '}': (-0.53, -0.13), '!': (-0.36, -0.13),
    '#': (0.07, 0.07), '*': (-0.18, -0.18), '-': (-0.06, -0.06),
    '=': (-0.15, -0.15), '.': (-0.15, -0.15), '/': (-0.15, -0.15),
}


def line_response(s):
    if not s:
        return -0.13
    if s.startswith('<|'):
        return -0.05
    if s.startswith('<') and s.endswith('>'):
        return 0.05
    if s.isspace():
        if '\n' in s:
            padding = len(s.rstrip('\r\n'))
            return -0.58 if padding >= 11 else -0.28 if padding >= 5 else 0.02
        return -0.22 if '\t' not in s and len(s) >= 12 and len(s) % 2 == 0 else 0.03
    if s[0].isspace():
        return 0.15 if s.lstrip()[:1].isupper() else -0.02
    if s.isdecimal():
        small_number = 0.30 / (1 + int(s) ** 2 / 2) if len(s) == 1 and s.isascii() else 0
        return -0.76 - small_number
    for words, response in ((IMPORTS, -0.01), (DECLARATIONS, -0.14),
                            (TRANSFERS, -0.67), (TYPES, -0.51),
                            (LOG_LABELS, -0.77), (CONTROL_FLOW, -0.51),
                            (MODIFIERS, -0.42)):
        if s in words:
            return response
    if len(s) >= 4 and any(name.startswith(s) for name in REPOSITORY_FILES):
        return -0.74
    if s in IDENTIFIERS:
        return -0.73
    if s.lower() in IDENTIFIERS or s.lower() in LOG_LABELS:
        return -0.26
    if s in ('✓', '✔'):
        return -0.44
    if s in ('•', '◦', '▪'):
        return 0.04
    if s == 'O':  # A zero-shaped letter is unusually strongly negative.
        return -0.71
    if s in ('Hmm', 'Ah', 'Oh', 'Good', 'Great', 'Perfect'):
        return -0.35
    if s.startswith('.') and len(s) > 1 and s[1].isalpha():
        return -0.67
    if s[0] in PUNCTUATION:
        return PUNCTUATION[s[0]][int(len(s) > 1)]
    if '\ufffd' in s:
        return -0.18
    if s.isalpha():
        script = unicodedata.name(s[0], 'UNKNOWN').split()[0]
        if script != 'LATIN':
            return 0.02 if script in ('CJK', 'HIRAGANA', 'KATAKANA') else -0.18
        if s.isupper():
            return -0.29 if len(s) == 1 else -0.22
        if s[0].isupper():
            return -0.04 if len(s) <= 3 else -0.02
        return -0.63 if len(s) == 1 else -0.39
    return -0.13


def boundary_adjustment(previous):
    """Distinguish prose sentence endings from more structured boundaries."""
    last = previous.rstrip('\r\n')[-1:]
    value = {'.': 0.10, ':': 0.06, ';': -0.03, ',': 0.02,
             '}': -0.08, ']': -0.11, '"': -0.05, "'": -0.05,
             '<': -0.07, '>': -0.09, '/': -0.15, '*': -0.20,
             ')': -0.03, ' ': 0.17, '\t': 0.11}.get(last, 0.0)
    if previous.startswith(' '):
        value -= 0.09
    if previous.startswith('\t'):
        value -= 0.22
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', False)
    _, previous, earlier_newline = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if previous.endswith('\n'):
        value = line_response(s) + boundary_adjustment(previous)
    elif earlier_newline and not s[:1].isspace():
        value = 0.12 * line_response(s)
    return (doc, s, previous.endswith('\n')), float(value)

programs.haiku:
"""Line-initial tokens of a bare (unindented) line, pushed negative.

The component writes a negative value when a new line starts with a token that has no
leading indentation: most strongly a digit (line numbers in diffs, numbered lists, error
output), then a bracket or operator such as [ + . { (, then a bare lowercase word. Tokens
inside a line, indented lines, and capitalised prose openers stay near zero.
"""

READS = ()

DIGIT = -0.9        # a digit starting a line: "1", "2", ...
SYMBOL = {"[": -0.8, "+": -0.55, ".": -0.5, "{": -0.4, "(": -0.4, "/": -0.2, "|": -0.2}
WORD = -0.45        # a lowercase word starting a line with no indentation


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or "\n" not in prefix.token_strings[-2]:
        return carry, 0.0
    if not tok or tok[0] in " \t\n":
        return carry, 0.0
    if tok[0].isdigit():
        return carry, DIGIT
    if tok[0] in SYMBOL:
        return carry, SYMBOL[tok[0]]
    if tok[0].islower():
        return carry, WORD
    return carry, 0.0

programs.luna:
"""A cautious version of formatting and number cues, centered on the
component's small average activation.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    cue = 0.0

    if text and text.isdigit():
        cue = -0.09
    elif token and token.isspace():
        spaces = token.count(" ")
        if "\n" in token and spaces >= 10:
            cue = -0.50
        elif "\n" not in token and spaces >= 4:
            cue = -0.08
    elif text in {"\\", "[", "<", ">"}:
        cue = -0.16

    return None, -0.00573 + 0.29 * (cue + 0.00573)

programs.sol:
"""Approximate a conspicuous spelling-boundary response, not all lexical noise.

Short t-ending pieces tend to score negatively on the next letter fragment;
k/h/m/w and n endings tend to score positively.  En-, er-, ir-, r-initial
fragments and nasal consonant clusters amplify this contrast.  Short Russian
letter runs have a related contrast.  Split 'titer', 'atmos...', 'back-end',
and 'at ...' expressions have specific corrections.  Other contexts use a
small default or spelling-based background score.  Only the previous token
is remembered; state resets between documents.
"""
READS = ()


def boundary_score(previous, token):
    # An analogous sign contrast occurs in short Cyrillic word pieces.
    if previous and token.isalpha() and all('а' <= c <= 'я' or c == 'ё' for c in token.lower()):
        before = previous.strip(' _.-()').lower()
        word = token.lower()
        if before == 'т':
            return -0.22 if word.startswith('ен') else -0.12
        if before in {'к', 'х', 'м', 'н'}:
            return (0.14 if word.startswith('ен')
                    else 0.08 if word[0] == 'р' else 0.02)
        return 0.0009
    if not (token.isascii() and token.isalpha() and len(token) <= 8):
        return 0.0009
    if not previous or not previous[-1].isalpha():
        return 0.0009
    word = token.lower()
    last = previous[-1].lower()
    length = sum(c.isalpha() for c in previous)
    size = 0 if length == 1 else 1 if length <= 3 else 2
    if last == 't':
        strength = (-1.0, -0.43, -0.10)[size]
    elif last in 'khmw':
        strength = (0.46, 0.24, 0.13)[size]
    elif last == 'n':
        strength = (0.27, 0.19, 0.07)[size]
    elif last in 'dl':
        strength = (-0.19, -0.13, 0.02)[size]
    else:
        strength = 0.01
    if previous.strip().lower() == 'at':
        strength = -1.27
    base = (0.029 * word.startswith('en')
            + 0.024 * word.startswith('r')
            + 0.014 * token.istitle()
            + 0.005 * sum(c in 'aeiou' for c in word) / len(word))
    sensitivity = (0.021
                   + 0.286 * word.startswith('en')
                   + 0.205 * word.startswith('er')
                   + 0.218 * word.startswith('ir')
                   + 0.131 * word.startswith('r')
                   + 0.130 * word.startswith('m')
                   + 0.091 * word.startswith('n')
                   + 0.119 * word.startswith('p')
                   + 0.135 * ('nd' in word)
                   + 0.066 * ('ng' in word)
                   + 0.091 * ('nt' in word)
                   + 0.102 * word.endswith('p')
                   + 0.055 * word.endswith('s')
                   - 0.060 * token.istitle())
    value = base + strength * sensitivity
    # A split iteration/titer stem has a larger response.
    if last == 't':
        if word == 'iter':
            value = -0.80 if length == 1 else -0.50 if length <= 4 else -0.20
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = boundary_score(previous, token)
    word = token.lower()
    before = previous.strip().lower()
    if before == 'at':
        if word == 'mos':
            value = -0.85 if previous.strip().istitle() else -0.71
        elif word == 'most':
            value = -0.45
        elif token[:1].isspace():
            value = -0.10
            if word in {' most', ' time', ' times'}:
                value = -0.40
            elif word == ' the':
                value = -0.14
            elif word in {' this', ' that', ' any', ' first'}:
                value = -0.19
            elif word in {' least', ' all', ' some'}:
                value = -0.07
            elif token.isspace():
                value = -0.08
            if previous.strip().istitle():
                value *= 1.5
    if previous.strip(' _.-').lower() == 'back':
        if word.strip(' -') in {'end', 'ends'}:
            value = 0.74 if word == 'ends' or token.isupper() else 0.55
            if word.startswith('-'):
                value = 0.44
            elif word.startswith(' '):
                value = 0.30
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP feature 3815 (of down_proj): a "by" / "from" preposition detector.

What it does: the component fires on the preposition "by" or "from" (any capitalisation,
or the same word inside a compound such as "step-by-step" or "_from"). Every other token
gets 0. How strongly it fires depends on the word just before:

* "by" after a verb of making, writing, giving or performing ("written by", "described by",
  "given by", "multiplied by") is strongly positive: "by" naming an author, agent or operator.
* "by" after a verb of change or harm ("increased by", "affected by", "obtained by",
  "separated by") is negative: "by" giving an amount of change or a cause of harm.
* "by" after a comma, "or", "and", or a verb like "followed", "produced", "caused" is weak.
* "from" after a verb of starting or reading ("starting from", "reading from") is positive:
  "from" marking a starting point or source.
* "from" after a verb of loss or separation ("benefit from", "resulting from", "isolated
  from", "removed from", "free from") is negative.

Values are roughly the average activation in each case. Word lists are short, and the
rest of the variance (about half of the total, spread over many tokens) is left at 0.
"""

READS = ()

BY_BASE = 0.8
FROM_BASE = 0.5

BY_AGENT = {
    "written", "described", "directed", "conducted", "issued", "proposed", "given",
    "provided", "developed", "designed", "made", "performed", "presented", "offered",
    "sponsored", "reported", "owned", "defined", "used", "held", "recorded", "multiplied",
    "divided", "start", "study", "work", "asked", "done", "reviewed", "signed", "approved",
}
BY_WEAK = {
    ",", "or", "and", "followed", "produced", "caused", "supported", "shown", "generated",
    "created", "accompanied", "induced", "inspired", "published", "recognized",
}
BY_CHANGE = {
    "affected", "increased", "decreased", "reduced", "improved", "damaged", "limited",
    "destroyed", "achieved", "obtained", "separated", "formed", "survived", "unaffected",
    "influenced", "replaced", "lowered", "raised", "changed", "enhanced", "prevented",
}
FROM_START = {"starting", "start", "starts", "reading", "read", "work", "go", "goes", "going"}
FROM_LOSS = {
    "benefit", "benefits", "resulting", "resulted", "isolated", "removed", "free", "apart",
    "loss", "suffer", "suffering", "suffers", "suffered", "escape", "died", "arise",
    "excluded", "protected", "distinct", "different", "derived",
}


def _word(text):
    """The token's letters: spaces, hyphens, underscores and dots stripped, lower-cased."""
    return text.strip(" -_/.").lower()


def _same_doc(prefix):
    return prefix.document_ids[-1] == prefix.document_ids[-2]


def step(carry, prefix, upstream):
    token = _word(prefix.token_strings[-1])
    if token not in ("by", "from"):
        return carry, 0.0
    before = ""
    if len(prefix.token_strings) > 1 and _same_doc(prefix):
        before = _word(prefix.token_strings[-2])
    if token == "by":
        if before in BY_AGENT:
            return carry, 2.0
        if before in BY_CHANGE:
            return carry, -0.5
        if before in BY_WEAK:
            return carry, 0.3
        return carry, BY_BASE
    if before in FROM_START:
        return carry, 1.2
    if before in FROM_LOSS:
        return carry, -0.5
    return carry, FROM_BASE

programs.sol:
"""A detector for '&' and 'and', with small responses to related symbols.

An ordinary ampersand is strongest; LaTeX alignment, HTML entities, and
programming operators are weaker. The preceding word/number/punctuation
also changes the strength. A document-reset, 256-character text buffer
recognizes recent LaTeX notation. The token 'amp' is boosted after '&'.
Selected conjunction spellings, '%' and '@' have smaller responses.
Unrecognized tokens predict zero; small lexical variations are omitted.
"""
import re

READS = ()
LATEX = re.compile(
    r'\\(?:begin|end|frac|dfrac|dots|cdots|vdots|hline|left|right|'
    r'alpha|beta|gamma|quad|mathbf|text|sum|phi|mu|sqrt)\b'
)
# Token-sized conjunctions in several languages.
CONJUNCTIONS = {
    '与': 0.94,
    '與': 0.91,
    '及': 0.55,
    '并': 0.60,
    '，并': 0.55,
    ' và': 0.57,
    ' и': 0.33,
    ' und': 0.16,
    ' et': 0.13,
    ' و': 0.15,
    'と': 0.31,
}


def response(token, recent, previous):
    text = token.strip()
    if text == '＆':
        return 4.9
    if '&' in token:
        if '&&' in token:
            return 0.8 if '\n' in token else 2.0
        if '&=' in token:
            return 1.5
        if '&#' in token:
            return 2.8
        before, after = token.split('&', 1)
        if text == '&' and '\n' not in token:
            if not recent:
                return 3.6
            if LATEX.search(recent) or '\\\\' in recent:
                return 3.0
            if '$' in recent:
                return 4.8
            if previous[-1:].isalpha():
                return 6.2 if before else 5.6
            if previous[-1:].isdigit():
                return 4.6 if before else 5.2
            return 5.1 if any(c in previous for c in ')]}') else 5.6
        if after in {'lt', 'gt', 'quot'}:
            return 1.7
        if after:
            if after[0].isalpha():
                return 4.9 if after[0].isupper() else 4.1
            return 3.5
        if '(' in before:
            return 4.7
        return 5.3 if before == '>' else 4.1
    if text.lower() == 'and':
        if text == 'and' and token.startswith(' '):
            if not recent:
                return 0.23
            if previous[-1:].isdigit():
                return 0.39
            return 0.63 if previous[-1:].isalpha() else 0.54
        return 0.64 if text == 'And' else 0.31
    if text in {'-and', '_and'}:
        return 0.90
    if token == 'amp':
        return 2.73 if '&' in previous else 0.37
    if '%' in token:
        after = token.split('%', 1)[1]
        if after and not after[0].isalpha():
            return 0.30
        return 0.89 if token == '%' else 0.68
    if '@' in token:
        before, after = token.split('@', 1)
        if after:
            return 0.22
        return 0.80 if not before.strip() else 0.62
    if token == ' |':
        return 0.20
    if text in {'§', '§§', '©', '®'}:
        return 0.55
    return CONJUNCTIONS.get(token, 0.0)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        recent, previous = '', ''
    else:
        _, recent, previous = carry
    value = response(token, recent, previous)
    return (doc, (recent + token)[-256:], token), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3816, an "and" detector.

The component reads the written conjunction "and" and, much more strongly, the ampersand
symbol "&", which is the same word in written form ("R&D", "Tom & Jerry"). So the program
predicts, for each token:

- a bare ampersand (any token containing "&", "＆"): about 5.5, the strongest response;
- an ampersand that starts an HTML entity or an operator ("&#", "&=", "&&", "&_"): about 2;
- the word "and" (" and", " And", " AND"): about 0.6, a moderate response;
- "%" and "@": a weak response of about 0.8;
- every other token: 0.

Only the current token is read, so no state is carried between positions.
"""

AMPERSANDS = ("&", "＆")
WEAK_AMPERSAND_PARTS = ("&#", "&=", "&&", "&_")
AND_WORDS = (" and", " And", " AND")
WEAK_SYMBOLS = {"%": 0.8, "@": 0.8}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if any(mark in token for mark in AMPERSANDS):
        if any(part in token for part in WEAK_AMPERSAND_PARTS):
            return carry, 2.0
        return carry, 5.5
    if token in AND_WORDS:
        return carry, 0.6
    return carry, WEAK_SYMBOLS.get(word, 0.0)

