"""Recognize coordinating “and” words and common separator symbols."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "&" in token:
        return None, 5.5
    if token.strip() == "|" and token.startswith(" "):
        return None, 0.24
    word = token.strip(" \t\r\n.,;:!?()[]{}\"'").casefold()
