READS = ()

# Translation, transmission, turning, crossing, transparency and transaction.
COUNTERPARTS = {
    '翻译': -2.2, '翻譯': -2.2, '译': -1.1, '譯': -1.1,
    '传输': -1.5, '傳輸': -1.5, '传递': -2.2, '傳遞': -2.2,
    '传': -1.0, '傳': -1.0, '伝': -1.6,
    '转': -1.0, '轉': -1.2, '転': -1.0, '转型': -1.2,
    '转让': -2.2, '轉讓': -2.2, '渡': -0.95,
    '透明': -3.5, '透': -4.1, '交易': -1.6,
    '交通': -1.8, '穿越': -2.6, '移植': -2.3,
}
OTHER_PREFIXES = {' пер': -1.3, ' перев': -0.75, ' tras': -1.05,
                  ' 전': -1.05}

# More specific forms precede their broader families.
FAMILIES = (
    ('translat', -3.2),
    ('transfer', -3.0),
    ('transact', -2.2),
    ('transition', -2.5),
    ('transient', -2.9),
    ('transcription', -3.5),
    ('transcripts', -3.5),
    ('transcript', -4.5),
    ('transpar', -4.0),
    ('transluc', -4.0),
    ('transgender', -4.8),
    ('transplantation', -3.0),
    ('transplant', -4.1),
    ('transformer', -1.3),
    ('transformation', -1.6),
    ('transform', -2.1),
    ('transportation', -2.7),
    ('transport', -2.4),
    ('transmi', -2.7),
    ('transpos', -3.3),
    ('transc', -3.3),
    ('trans', -2.0),
)


def token_value(token):
    text = token.strip().lstrip('._-/(')
    word = text.lower()
    if word == 'trans':
        value = -7.0
        if token.startswith('-'):
            value = -8.6
        elif token == 'Trans':
            value = -7.6
        elif text.isupper():
            value = -6.5
    elif word in ('tran', 'rans', 'transl', 'transf', 'transit'):
        value = {'tran': -1.8, 'rans': -2.2, 'transl': -5.4,
                 'transf': -4.0, 'transit': -6.3}[word]
        if word == 'tran' and text.isupper():
            value = -4.0
        elif word == 'transit' and text[:1].isupper():
            value = -5.3
    else:
        value = OTHER_PREFIXES.get(token, COUNTERPARTS.get(word, 0.0))
        for stem, strength in FAMILIES:
            if word.startswith(stem):
                value = strength
                break
        if word.startswith(('translation', 'translated', 'translating')):
            value = -2.7
        elif word.startswith('transfer') and text[:1].isupper():
            value = -3.4
        elif word == 'transactions':
            value = -2.8
        elif word == 'transcript' and text[:1].isupper():
            value = -5.8
        elif word == 'transformed':
            value = -1.3
        elif word in ('transforms', 'transforming'):
            value = -1.6
        elif word in ('transported', 'transporting', 'transporter'):
            value = -1.8
        elif word.startswith('transport') and text[:1].isupper():
            value = -2.7
        elif word == 'transmitted':
            value = -2.3
    return value, word


ENDINGS = {'s', 'ed', 'ing', 'er', 'ers', 'al', 'ly',
           'ation', 'ations', 'ational', 'ative'}


def completion(piece):
    """The next written part of a trans- word, grouped by its word family."""
    if piece == 'l':
        return -3.2
    if piece.startswith('cript'):
        return -4.7
    if piece == 'it':
        return -4.6
    if piece.startswith('iting'):
        return -3.4
    if piece.startswith('plant'):
        return -2.8
    if piece == 'c' or piece.startswith(('crib', 'pos')):
        return -2.2
    if piece == 'f':
        return -2.0
    if piece.startswith(('itiv', 'ient', 'lat', 'fer', 'form')):
        return -1.4
    if piece.startswith(('vers', 'mit', 'pil', 'pl', 'cod', 'miss')):
        return -1.1
    return -0.4


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_word, old_value, parts = '', 0.0, 0
    if carry is not None and carry[0] == doc:
        _, old_word, old_value, parts = carry
    value, word = token_value(token)
    if old_word.startswith('trans') and token.isalpha() and token.islower():
        if old_word == 'trans':
            value = completion(word)
        elif old_word in ('transl', 'transf'):
            value = -1.5
        elif word in ENDINGS:
            value = -1.3 if parts == 0 else -0.5
        else:
            value = -0.3
        return (doc, old_word + word, value, parts + 1), value
    if old_word.startswith('trans'):
        if token == ' of':
            value = 0.5 * old_value
        elif token in (' to', ' into', ' by', ' in'):
            value = -0.2
    return (doc, word, value, 0), value

"""Approximate a no-space boundary response.

A word or number directly after a comma, colon, semicolon or operator gets a
negative activation. Spaces, subword continuations and continued numbers mostly
get zero. Numbers following letters also respond, especially after longer words.
Separate rules cover comma-prefixed tokens, chat role labels, backslashes and
nonbreaking spaces. CJK ideographs, kana and Hangul are excluded from the word
rule. Only the last two tokens are retained, resetting at document boundaries.
"""

import unicodedata

READS = ()

# (number, alphabetic word) immediately following each punctuation mark.
SEPARATORS = {
    ',': (-2.17, -1.70),
    ':': (-1.26, -1.05),
    ';': (-1.66, -1.13),
    ')': (-1.64, -1.10),
    '=': (-0.68, -0.46),
    '+': (-0.67, -0.41),
    '-': (0.05, -0.07),
    '*': (-0.50, -0.33),
    '/': (-0.05, 0.00),
    '&': (-1.11, -0.65),
    '|': (-0.75, -0.50),
    '#': (-0.75, -0.55),
}


def word_letter(c):
    return c.isalpha() and not any(script in unicodedata.name(c, '')
                                  for script in ('CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL'))


def response(s, prev, before):
    if not s or (s[0].isspace() and s != '\xa0') or s.startswith('<|'):
        return 0.0
    if s.startswith(',') and len(s) > 1:
        if word_letter(s[1]):
            return -1.23 if len(s) == 2 else -1.55
        if s[1] in '@+-_&%*':
            return -1.0
        if s[1] in '([{.':
            return -0.75
        return -0.33 if s[1] in '\\"\'' else 0.0
    if not prev or prev[-1].isspace():
        return 0.0
    if prev == '<|im_start|>':
        return -0.65 if s in {'user', 'assistant', 'system', 'tool'} else 0.0
    end = prev[-1]
    number, word = s.isdecimal(), word_letter(s[0])
    if s == '\xa0':
        return {'.': -0.68, ':': -0.78, ')': -0.57}.get(end, 0.0)
    if s.startswith('\\'):
        return {',': -1.39, ';': -1.07, ')': -0.60, ':': -0.70}.get(end, 0.0)
    if not (number or word) or end.isdigit():
        return 0.0
    if end.isalpha():
        if not number:
            return 0.0
        if not end.isascii():
            return -0.85
        rate, limit = (0.07, 0.45) if end.isupper() else (0.17, 0.70)
        return -min(limit, rate * len(prev.strip()))
    if prev.endswith('::'):
        return 0.0
    if end == '.':
        if number:
            return 0.06 if prev == '.' and before[-1:].isdigit() else -0.70
        return -0.38 if prev.endswith('().') else -0.65
    if prev[0].isspace():
        special = {'=': (-1.89, -1.29), '+': (-1.40, -0.85),
                   '-': (-0.52, -0.17), '/': (-0.84, -0.18)}
        if end in special:
            return special[end][0 if number else 1]
    if end in '?!':
        return -1.30 if number else -0.80
    if end in '，。、：':
        return -0.65 if number else -0.32
    if end == '\ufffd':
        return -0.74 if number else -0.18
    if end in '<>':
        return -0.80 if number else -0.12
    if number and end in '$×√≈→≠−–≥≤⇒~':
        return -0.70
    if end in '…”' and word:
        return -0.90
    return SEPARATORS.get(end, (0.0, 0.0))[0 if number else 1]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    return (doc, token, prev), float(response(token, prev, before))

"""Backslash escapes versus presentation commands.

Predict positive activation for newline/tab escapes, literal punctuation,
and initial-capital names after a backslash. Predict negative activation
for TeX font/layout prefixes and their split-name continuations, and for
inline style tags. Greek-letter commands are mostly quiet. Other text is
zero. Values are approximate training means; state resets per document.
"""
READS = ()

GREEK = set('''alpha beta gamma delta epsilon zeta eta theta iota kappa
lambda mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega'''.split())
STYLE_TAGS = {'span', 'em', 'code', 'strong', 'text', 'label'}
# TeX command names or their initial subwords, grouped by familiar roles.
COMMAND_GROUPS = (
    (-3.75, {'text'}),
    (-3.15, {'mathrm'}),
    (-2.4, {'math'}),
    (-2.8, {'rm', 'bold', 'ensure', 'operator', 'display'}),
    (-1.55, {'left', 'hat', 'over', 'wid', 'wide', 'hs', 'vec', 'quad',
             'phant', 'var', 'label', 'pu', 'bm'}),
    (-1.05, {'right', 'big', 'ld', 'til', 'Large', 'huge', 'small'}),
    (2.4, {'int', 'sum', 'prod'}),
    (1.1, {'sin', 'cos', 'tan', 'exp', 'log', 'ln', 'lim', 'inf', 'sup',
           'in', 'to', 'ge', 'le', 'approx', 'equiv', 'sim', 'subset',
           'end', 'cite', 'pm'}),
    (0.0, {'begin', 'ref', 'Rightarrow', 'Leftarrow', 'Longrightarrow'}),
    (0.35, {'times', 'new', 'non'}),
    (1.5, {'item', 'param', 'return', 'brief', 'count'}),
)


def after_backslash(token, previous):
    for value, names in COMMAND_GROUPS:
        if token in names:
            return value
    if token.lower() in GREEK:
        return 0.5 if token in {'nu', 'mu', 'xi'} else 0.0
    if token in {'n', 't'} or (token.startswith('n') and token[1:2].isupper()):
        n_slashes = len(previous) - len(previous.rstrip('\\'))
        lead = previous[:-n_slashes]
        value = 1.2 / n_slashes
        if lead.endswith(('"', "'", '`')):
            value += 0.45 + 0.45 * lead.endswith(('("', "('"))
        return value - 0.25 * (lead == ' ')
    if token[:1] in {'n', 't'} and token.isalpha():
        return 2.7
    if token[:1].isupper():
        return 2.0
    if token.startswith('\\"'):
        return 1.0
    if token.startswith('"'):
        return 3.2 if ',' in token or '/' in token else 2.15
    if token.startswith('{') or token.startswith('/') or token.isdigit():
        return 2.25
    if token in {'}', '%', '*', '|', '$', 'Vert', '’', "'"}:
        return 1.3
    if token in {'[', '('}:
        return 0.65
    if token.startswith(',') or token == ')':
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, command = '', ''
    if carry is not None and carry[0] == doc:
        previous, command = carry[1:]
    value = 0.0
    if token in {r'\n', r'\t'}:
        value = 0.69 if token == r'\n' else 0.47
    elif previous.endswith('\\'):
        value = after_backslash(token, previous)
    elif command == 'math' and token.isalpha():
        value = -2.85
    elif command and command + token == 'operatorname':
        value = -3.85
    elif command and command + token in {'mbox', 'hbox'}:
        value = -3.2
    elif command and command + token == 'displaystyle':
        value = -1.4
    elif token in STYLE_TAGS and previous.endswith('<'):
        value = -0.65
    elif token in STYLE_TAGS and previous.endswith('</'):
        value = -1.4
    if not token.isalpha():
        command = ''
    elif previous.endswith('\\'):
        command = token
    elif command:
        command += token
    return (doc, token, command), float(value)

