"""Predict responses to a small class of backslash-led code and math fragments.

Common escape and TeX command pieces are positive; several named TeX
commands and a closing-text tag are negative. Other tokens are left at zero.
"""
READS = ()


POSITIVE_COMMANDS = (
    "n", "count", "%", "’", "pm", "end", "sum", "to", "g",
    "Int", "Letter", "terr",
)


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    current = tokens[-1]
    same_document = (
        len(tokens) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = tokens[-2] if same_document else ""

    if previous.endswith("\\"):
        if current.startswith(("operator", "label", "$")):
            return None, -1.6
        if current.startswith(POSITIVE_COMMANDS):
            return None, 1.3
        if current.startswith("//"):
            return None, 2.4

    if previous.endswith("operator") and current.startswith("name"):
        return None, -1.6
    if previous.endswith("</") and current.startswith("text"):
        return None, -1.2
    return None, 0.0

programs.sol:
"""Mostly an end-of-document marker, with weaker chat and continuation cues.

Predict a large positive value for the explicit end-of-text token, smaller
values for chat delimiters and the word 'assistant', and weak responses to
'also' and two sentence-opening discourse connectives. Structural responses
are reduced near the beginning of a document. Everything else is zero.
"""
from math import sqrt

READS = ()

# Asymptotic response and the reduction at the start of a document.
CHAT_MARKERS = {
    '</tool_response>': (0.73, 0.53),
    '<tool_response>': (0.10, 0.33),
    '<think>': (0.24, 0.35),
    '</think>': (0.06, 0.45),
    '<|im_end|>': (0.035, 0.50),
    '</tool_call>': (-0.03, 0.29),
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    token = prefix.token_strings[-1]
    early = 1.0 / sqrt(position + 1.0)

    if token == '<|endoftext|>':
        value = 22.65 - 6.25 * early
        if position == 0:
            value = 13.59
    elif token in CHAT_MARKERS:
        base, reduction = CHAT_MARKERS[token]
        value = base - reduction * early
    elif token.strip().lower() == 'assistant':
        if token == 'assistant':
            value = 0.96 - 0.40 * early
        elif token == 'Assistant':
            value = 3.4
        else:
            value = 0.6
    elif token.strip().lower() == 'also':
        value = 0.23 if token.strip().islower() else 0.6
    elif token.strip() == 'Additionally':
        value = 0.6
    elif token.strip() == 'Alternatively':
        value = 0.38 if token.startswith(' ') else 0.15
    else:
        value = 0.0
    return (doc, position), value

