"""Approximate a sparse lexical feature: distinctive word pieces get a positive
response, especially long, capitalized, or non-Latin ones. Common glue words
and ordinary punctuation usually get none. This is a surface-form proxy, not
a lookup table of particular vocabulary items.
"""
READS = ()

FUNCTION_WORDS = {
    "a", "an", "the", "and", "or", "but", "if", "as", "at", "by",
    "for", "from", "in", "into", "of", "on", "onto", "to", "with",
    "without", "is", "are", "was", "were", "be", "been", "being",
    "do", "does", "did", "have", "has", "had", "not", "no", "it",
    "its", "he", "she", "they", "we", "you", "i", "my", "our",
    "their", "this", "that", "these", "those", "who", "what", "which",
    "when", "where", "why", "how", "can", "could", "will", "would",
    "shall", "should", "may", "might", "must", "than", "then", "so",
    "there", "here", "also", "just", "very", "more", "most", "some",
    "any", "all", "each", "both", "such", "only", "about", "over",
    "after", "before", "up", "down", "out", "through", "because",
}


