    token = prefix.token_strings[-1]
    letters = [char for char in token if char.isalpha()]
    if not letters:
        # Rare control markers and replacement characters can be informative.
        if token.startswith("<|") and token.endswith("|>"):
            return None, 0.0255 + 0.15 * (0.35 - 0.0255)
        if "\ufffd" in token:
            return None, 0.0255 + 0.15 * (0.35 - 0.0255)
        if any(ord(char) > 127 and not char.isspace() for char in token):
            return None, 0.0255 + 0.15 * (0.12 - 0.0255)
        return None, 0.0255

    # CJK ideographs and other non-Latin letters can be whole short words.
    if any(ord(char) > 0x2ff for char in letters):
        value = 0.38 if len(letters) < 3 else 0.55
        return None, 0.0255 + 0.15 * (value - 0.0255)

    word = "".join(letters)
    lower = word.lower()
    if lower in FUNCTION_WORDS:
        return None, 0.0255 + 0.15 * (0.01 - 0.0255)

    # Long lexical pieces and names are the clearest surface signal.
    if any(char.isupper() for char in letters):
        value = 0.48 if len(word) >= 3 else 0.30
        if word.isupper() and len(word) >= 3:
            value += 0.10
    elif len(word) >= 6:
        value = 0.42
    elif len(word) >= 4:
        value = 0.28
    elif len(word) >= 2:
        value = 0.12
    else:
        value = 0.08

    return None, 0.0255 + 0.15 * (value - 0.0255)

programs.sol:
"""Negative response to the spelling OR, strongest in short word fragments.

The ordinary words 'for' and 'or' are weaker than short OR fragments.
Long words and agent suffixes (-ator, -ctor, etc.) usually dilute the
response. Common OR-ending nouns, Latin comparatives, and some foreign
spellings have separate strengths. OR/ORS pieces use the previous
token's final letter to refine their strength, within the same document.
This is a spelling approximation, not a meaning parser.
"""

READS = ()
COMPARATIVES = {'junior', 'senior', 'anterior', 'posterior', 'interior',
                'exterior', 'superior', 'inferior'}
OR_NOUNS = {'author', 'color', 'door', 'honor', 'labor', 'mayor'}


def activation(token, previous=''):
    text = token.strip()
    word = text.lower().lstrip('_./-')
    spaced = token[:1].isspace()
    # Function words versus a syllable continuing an earlier token.
    if word == 'for':
        return -0.96 if spaced else -1.20
    if word == 'or':
        if spaced:
            return -2.4 if text.isupper() else -1.47
        if text[0] in '_./-':
            return -2.25
        if text == 'Or':
            return -2.15
        inside = bool(previous and previous[-1].isalpha())
        value = -1.6
        if inside:
            value = -3.0 if previous[-1].lower() in 'tsr' else -3.8
        return value - (0.6 if text.isupper() else 0.0)
    # Familiar whole-word families are calibrated separately.
    if word in {'nor', 'vor'}:
        return -4.2
    if word in {'major', 'minor', 'prior'}:
        return {'major': -2.0, 'minor': -3.0, 'prior': -2.5}[word]
    if word in COMPARATIVES:
        return -1.1
    if word.rstrip('s') in OR_NOUNS:
        return -1.0
    # Related spellings, including Cyrillic OR and accented O + R.
    if 'ор' in word:
        if word == 'ор':
            return -2.7
        if word == 'вор':
            return -3.6
        if word.endswith('атор'):
            return -0.4
        if word.endswith('ор'):
            return -1.8 if len(word) <= 4 else -0.4
        return -0.2
    if any(s in word for s in ('ør', 'ör', 'ór', 'ور')):
        return -1.3 if len(word) == 2 else -0.6 if len(word) <= 4 else -0.2
    if word in {'或', '或者', 'или', 'oder'}:
        return -0.5
    if 'or' not in word:
        return 0.0
    if word.startswith('horr'):
        return -3.5 if len(word) <= 7 else -1.0
    if word in {'born', 'sorry', 'worst'}:
        return -0.9
    # Otherwise use OR's location, fragment length, and common suffixes.
    before, after = word.rsplit('or', 1)
    if not after:
        if len(word) == 3:
            if before == 'o':
                return -1.8
            if before in 'ctgd':
                return -2.3
            return -3.1 if spaced else -3.7
        if word.endswith(('ator', 'ador', 'ctor', 'motor', 'sensor')):
            return -0.25
        if word in {'poor', 'floor', 'error', 'mirror', 'behavior'}:
            return -0.1
        if word.endswith(('itor', 'utor')):
            return -2.1 if len(word) == 4 else -0.25
        if len(word) <= 5 and all(c not in 'aeiouy' for c in before[-2:]):
            return -2.3
        if len(word) <= 4:
            return -2.0
        return -0.8 if len(word) == 5 else -0.3
    if not before:
        if after == 's':
            coronal = previous and previous[-1].lower() in 'tsr'
            return -1.9 if coronal else -2.75
        if len(after) <= 2:
            if after[0] in 'kr':
                return -1.9
            return -1.1 if after[0] in 'aeiouyg' else -0.6
    if len(word) <= 4:
        if before in {'b', 'h', 'd', 'g'} and after[0] in 'aeiou':
            return -0.6 if spaced and text.islower() else -2.4
        if before == 'f' and after == 'd':
            return -0.8
    return -0.09


def step(carry, prefix, upstream):
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
