"""Predict an L-like continuation after a labial consonant.

The preceding token supplies a gain: B/P/V/F are strongest, M/W weaker.
An initial L or vowel-plus-L supplies the current response. Longer
fragments and most leading spaces weaken it; nasal/sibilant onsets can be
negative. Related spellings in several scripts share these rules.
Only the immediately preceding token is retained, with document resets.
"""
READS = ()

LETTER_FOLD = str.maketrans(
    'бпвфмдгткрлнсзхйцаеиоуыэюяёβπφμبپفمايو',
    'bpvfmdgtkrlnszhjcaeiouieuaevpfmbpfmaiu',
)
LATERALS = frozenset('lλłلլל')
VOWELS = frozenset('aeiouy')
ENDING = {
    'b': 1.0, 'p': .75, 'v': .72, 'f': .53, 'm': .15,
    'w': .14, 'd': .08, 'g': .10, 't': .025, 'k': .025,
    'r': -.02, 'l': -.005, 'n': -.007, 's': -.009, 'h': .026,
}
VOWEL_L = {'a': .56, 'e': 1.38, 'i': 1.26,
           'o': 1.12, 'u': 1.06, 'y': .62}
OTHER_ONSETS = {
    'n': -.17, 's': -.16, 'p': -.03, 'r': .14,
    'h': .30, 'w': .21, 'a': -.03, 'e': .01,
    'i': .09, 'o': .08, 'u': .16, 'y': .13,
}
LENGTH_SCALE = (1.24, 1.0, .82, .55, .42)

KATAKANA_L = {'ラ': .5, 'リ': .65, 'ル': .8, 'レ': 1.55, 'ロ': 1.0}
KATAKANA_LABIALS = (('バビブベボ', 1.0), ('パピプペポ', .75),
                    ('フヴ', .53))


def previous_strength(text):
    for letters, value in KATAKANA_LABIALS:
        if text and text[-1] in letters:
            return value
    s = text.lower().translate(LETTER_FOLD)
    strength = ENDING.get(s[-1:], .014)
    # Labials a few characters back in the preceding fragment count weakly.
    if s[-1:] not in 'bpvfmw':
        for distance, decay in ((1, .15), (2, .13), (3, .08)):
            if len(s) > distance and s[-1-distance] in 'bpvfmw':
                strength += decay * ENDING[s[-1-distance]]
    if len(s) < 2 or not s[-2].isalpha():
        return strength * .925
    if s[-2] in 'au':
        return strength * 1.27
    return strength * (1.0 if s[-2] in 'eioy' else .835)


def continuation(text):
    original = text.lower()
    s = original.translate(LETTER_FOLD)
    word = s.lstrip()
    if not word:
        return .003 * 1.24
    first = word[0]
    if first in KATAKANA_L:
        scale = 1.0 if len(word) == 1 else .5
        return KATAKANA_L[first] * scale
    if first == 'λ':
        return 1.0 if len(word) == 1 else .6
    lateral = first in LATERALS
    vowel_l = (len(word) > 1 and first in VOWELS
               and word[1] in LATERALS)
    if word != s:
        return .09 if lateral or vowel_l else .003 * 1.24
    if lateral:
        if len(word) == 1:
            return 2.84 if original == 'л' else 2.0
        scale = LENGTH_SCALE[min(len(word), 5) - 1]
        return (1.8 if word[1] in VOWELS else 1.48) * scale
    if vowel_l:
        return VOWEL_L[first] * LENGTH_SCALE[min(len(word), 5) - 1]
    if len(word) > 1 and first in VOWELS and word[1] == 'n':
        return -.17
    return OTHER_ONSETS.get(first, .003) * 1.24


