import re

READS = ()
UL_SUFFIX = re.compile(r"ul(?:[aeiou]s?|ar)$", re.IGNORECASE)
TOOL_ENDS = ('</tool_call>', '</tool_response>')


def ending_values(previous):
    """Responses at a message end and at the following message start."""
    if previous in TOOL_ENDS:
        return 0.77, 1.67
    last = previous[-1:]
    if last in ('。', '？', '！'):
        return 1.38, 1.80
    if last in ('?', '!'):
        return 1.22, 1.71
    if last.isalpha():
        return (1.01 if last.isascii() else 1.08), 1.67
    return 1.25, 1.74


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, next_start, position = '', 1.70, 0
    else:
        _, previous, next_start, previous_position = carry
        position = previous_position + 1
    first = position == 0
    token = prefix.token_strings[-1]
    if token == '<|im_start|>':
        value = 0.703 if first else next_start
    elif token == '<|im_end|>':
        value, next_start = ending_values(previous)
        if first:
            value = 0.49
    elif previous == '<|im_start|>' and token in ('user', 'assistant'):
        if token == 'user':
            value = 0.197 if position == 1 else 0.104
        else:
            value = 0.098 if position == 1 else -0.015
    elif token == '</think>':
        value = 2.19
    elif token in ('<think>', '<tool_call>'):
        value = 1.47
        if first and token == '<tool_call>':
            value = 0.68
    elif token == '<tool_response>':
        value = 1.29
    elif token == '</tool_response>':
        value = 1.26
    elif token == '</tool_call>':
        value = 0.48 if first else 1.19
    else:
        value = 0.0
        lower = token.lower()
        if UL_SUFFIX.fullmatch(token):
            value = -0.45 if lower.startswith('ule') else -0.24
        elif (token[:1].isalpha() and
              previous.lower().endswith('ul') and not first):
            value = -0.09
    return (document, token, next_start, position), value

