        if word.startswith(('县', '縣')):
            return -5.0 if len(word) == 2 else -4.0
        if word.endswith(('省', '区', '區')):
            return -1.0
    if lower in ('.local', '-local', '_local', '(local'):
        return -0.55
    if word in FILE_SPELLINGS:
        return FILE_SPELLINGS[word]
    if lower == 'tests':
        return -0.05 if spaced else -0.3
    if lower == 'filename':
        return -0.4 if spaced else -0.5
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = lexical_value(prefix.token_strings[-1])
    if word.lower() == 'of':
        value = OF_AFTER.get(previous, OF_AFTER.get(previous.lower(), 0.0))
    return (doc, word), value

"""Detect capitalized token segments inside words, especially camelCase.

For example, the Name token after get has a large positive activation. Short
capitalized fragments are slightly weaker; initials, acronyms, and numeric
suffixes are weaker still. More trailing lowercase letters in the previous
token strengthen this signal, with a boost for familiar connector words.
Separate words are near zero, except capitalized document-initial tokens.
Escaped whitespace suppresses positive responses. Word-specific variation is
not modeled.
"""

READS = ()
CONNECTORS = frozenset(
    "to by in on at as of is or no if an be do up my for and not".split()
)
LOWERCASE = 'abcdefghijklmnopqrstuvwxyz'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    last = previous[-1:]
    n = len(previous) - len(previous.rstrip(LOWERCASE))
    value = 0.0

    if s and 'A' <= s[0] <= 'Z' and s.isalpha():
        title = len(s) > 1 and s.istitle()
        if not previous:
            value = 0.98 if title else 0.03
        elif 'a' <= last <= 'z':
            if title:
                if previous.strip(' .(_').lower() in CONNECTORS:
                    n = max(n, 3)
                value = 2.1
                if n == 1:
                    value -= 0.9
                elif n == 2:
                    value -= 0.3
                if len(s) <= 3:
                    value -= 0.2
            elif s.isupper():
                value = 0.4 * min(n, 4)
            else:
                value = 1.53
        elif 'A' <= last <= 'Z':
            value = 0.46 if title else -0.04
        elif last.isdigit():
            value = 0.38 if title else -0.05
        else:
            value = -0.055 if title else -0.02
    elif s.isdigit() and 'a' <= last <= 'z':
        value = 0.0 if n < 3 else 0.24

    if tail in ('\\n', '\\r', '\\t') and value > 0:
        value = 0.1
    return (doc, s, (tail + s)[-2:]), value

"""Approximate the strong negative arrival-word and 'arr'-fragment response.

Training showed weaker negatives for array, arrangement, arrow, board and
administrative vocabulary, some multilingual equivalents, delivery words,
and short double-r fragments. An arrival suffix split after 'arr' retains
the signal; selected following prepositions retain a smaller part of it.
Document boundaries reset the one-token memory. Unmatched tokens predict
zero, leaving the component's many weak or positive responses unmodeled.
"""
READS = ()

PUNCTUATION = '_.,;:()[]{}<>/\\\"\'`$=-'
ENGLISH_ARRIVAL_ENDINGS = {'ive', 'ived', 'ives', 'ival', 'ivals', 'iving'}
ARRIVAL_PREPOSITIONS = {
    'at': -1.6, 'of': -2.9, 'in': -0.6, 'on': -0.85, 'to': -0.75,
}


def word_form(token):
    return token.strip().strip(PUNCTUATION)


def token_response(token):
    form = word_form(token)
    word = form.lower()
    if word == 'arr':
        if token.lstrip().startswith(('(', '_', '$')):
            return -4.4
        return -5.0 if token[:1].isspace() and form == 'arr' else -5.6
    if word.startswith('arriv'):
        if word == 'arrivals':
            return -4.3
        return -5.4 if word.isascii() else -2.5
    if word in {'barr', 'carr'}:
        return -5.0 if form[:1].isupper() else -3.8
    if word.endswith('arr') and len(word) == 4:
        return -0.8 if word == 'narr' else -2.8
    if word == 'arra':
        return -2.9
    if 'array' in word:
        return -1.25
    if word.startswith(('arrang', 'arrow')) or word == 'angement':
        return -1.3
    if word.startswith('arr'):
        return -0.8
    if word in {'board', 'boards'}:
        return -1.3 if form[:1].isupper() else -0.9
    if word == 'administrative':
        return -0.9
    if word in {'err', 'orr', 'corr', 'rr'}:
        return -0.3 if word == 'err' else -0.8
    if word in {'到达', '抵达', '到来', '的到来'}:
        return -2.3
    if word in {'到', '到了', '进入', '来到', '到位', '不到'}:
        return -0.65
    if word.startswith('lleg'):
        return -2.0 if word == 'lleg' else -1.1
    if word in {'阵', '陣', '数组', '安排', 'массив', 'arreglo'}:
        return -1.1
    if word in {'delivery', 'delivers', 'delivering', 'attendance'}:
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = word_form(token).lower()
    value = token_response(token)
    arrival = word.startswith('arriv')
    if carry is not None and carry[0] == doc:
        previous, was_arrival = carry[1:]
        if previous == 'arr' and token.isalpha():
            if token.lower() in ENGLISH_ARRIVAL_ENDINGS:
                value = -3.9 if token == 'ive' else -5.0
                arrival = True
            elif token.startswith('iv'):
                value = -2.8
                arrival = True
        if was_arrival and token[:1].isspace():
            value += ARRIVAL_PREPOSITIONS.get(word, 0.0)
        elif token == ' of':
            if previous.startswith('arrang'):
                value -= 0.6
            elif 'array' in previous or previous in {'board', 'boards'}:
                value -= 0.33
    return (doc, word, arrival), value

programs.haiku:
"""Layer-0 MLP down-projection component 3834: an 'arrive' detector.

What it does, in plain terms: this component goes strongly negative on the
word "arrive" and its relatives ("arr", "arrived", "arrival", "arrives"), and
on bare name-like fragments such as " Barr" or " Carr". It goes moderately
negative on other "arr" words ("array", "arrange", "arrow", "arrested") and on
"array" inside code identifiers ("_array", ".toArray"). It is weaker on
"board" and "administrative", on the Chinese words for arrive or reach (到达,
到来, 到, 到了) and for "enter" (进入), and on "at" right after an arrive-word
("arrived at"). Every other token is predicted as 0.

The values are the typical activations on training text, so the program
predicts the component's size on each word. The word lists are the whole
program; no context or position is used beyond the previous token.
"""
import re

READS = ()

ARRIVE = re.compile(r"arr(i?v\w*)?")  # arr, arrive, arrived, arrival, arrives
FRAGMENT = {"barr", "carr", "parr", "marr"}  # bare name-like 'arr' fragments
BOARD = {"board", "boards", "boarding"}
REACH = {"到达": -2.0, "到来": -2.0, "到": -0.7, "到了": -0.7, "进入": -0.7}


def step(carry, prefix, upstream):
    """Stateless: the activation at the newest token, from its word and the one before."""
    w = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if ARRIVE.fullmatch(w.lstrip("(")):
        value = -5.5  # arrive, arrived, arrival, bare 'arr'
    elif w in FRAGMENT:
        value = -4.5  # ' Barr', ' Carr'
    elif w.lstrip("(").startswith("arr") or "array" in w or w == "массив":
        value = -1.3  # array, arrange, arrow, _array, .toArray
    elif w in BOARD:
        value = -1.0
    elif w == "administrative":
        value = -0.9
    elif w in REACH:
        value = REACH[w]
    elif w == "at" and ARRIVE.fullmatch(prev):
        value = -1.5  # 'arrived at'
    else:
        value = 0.0
    return carry, float(value)

