"""A token-local hand/tool signal with weaker responses to other body symbols.

手 ('hand') is strongest; its longer compounds are weaker. English hand is
negative except in the contrastive idiom 'other hand'. Japanese compounds
such as 相手 ('partner') and 選手 ('player') also weaken the hand response.
Longer 手 compounds are scaled down by their character count, with a few
common lexical exceptions. A 48-character history resets at each document.
Split byte tokens are checked for a completed 手. Other tokens return zero;
this is a lexical approximation, not a general classifier of manual activity.
"""
READS = ()

# Individual body characters, and the hand-held writing implement.
BODY = {
    '口': -1.4, '嘴': -2.3, '心': -0.94, '身': -0.79,
    '脚': -1.45, '腳': -1.6, '眼': -0.6, '腿': -0.68,
    '脸': -0.5, '筆': -1.1, '笔': -1.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    word = text.strip(' _-/.(').lower()
    value = 0.0
    if text == '手':
        japanese = any('\u3040' <= c <= '\u30ff' for c in tail)
        value = -5.9 if japanese else -7.0
        if tail.endswith(('相', '苦', '勝')):
            value = -4.3
        elif tail.endswith('選'):
            value = -3.2
    elif '手' in text:
        value = -6.1 / len(text) ** 1.3
        if text in {'的手', '用手'}:
            value = -5.6
        elif text in {'助手', '射手', '手套', '二手', '洗手'}:
            value = -1.0
    elif text in BODY:
        value = BODY[text]
    elif text == '工具':
        value = -1.3
    elif word == 'hand':
        value = -0.8
        previous = tail.lower().split()[-1:]
        if previous == ['other']:
            value = 0.21
        elif previous == ['one']:
            value = -0.3
        elif previous in (['left'], ['right']):
            value = -0.4
    elif word in {'hands', 'handbook', 'handheld'}:
        value = -1.45
    elif word in {'handmade', 'handwritten', 'handwriting'}:
        value = -0.8
    elif word == 'tool':
        value = -1.2
    elif word == 'tools':
        value = -1.0 if text[0].isspace() else -0.75
    elif word in {'manual', 'manually', 'manuals'}:
        value = -1.0
    elif word in {'mouth', 'mouths'}:
        value = -0.85 if text[0].isspace() else -0.3
    elif word in {'instrument', 'instruments', 'instrumental'}:
        value = -0.6
    elif text == ' thủ':
        value = -2.25
    elif text == ' рук':
        value = -1.8
    elif text == 'рук':
        value = -0.5
    elif text == ' mano':
        value = -0.85
    elif '\ufffd' in text and prefix.text_prefixes[-1].endswith('手'):
        # A byte fragment that completes the hand character.
        value = -7.8
    return (doc, (tail + text)[-48:]), value

programs.haiku:
"""Hand and tool words (layer-0 MLP component 3835).

A word detector for hands and hand tools. It responds negatively to the tokens of:
  - 手, the Chinese/Japanese character for "hand": strongest (about -6) on its own, weaker
    (about -2.5) inside compounds such as 手机 (phone), 洗手 (wash hands), 二手 (second-hand);
  - English "hand(s)" (weaker on "hand", stronger on "hands"), "tool(s)", "manual", and
    the Chinese 工具 (tool);
  - body parts used like hands: 口 / mouth (mouth), 心 (heart), 身 (body), with smaller values.
Everything else, including "handle", "arm", "feet", "head", is 0.
The values are the average activation for each group, so the sum of squares matches roughly.
"""

READS = ()

HAND_CHAR = "手"
HAND_WORD = {"hand": -0.5, "hands": -1.2}
TOOL_WORD = {"tool": -1.1, "tools": -1.0, "manual": -1.1, "工具": -1.4}
BODY_WORD = {"mouth": -0.8, "口": -1.0, "心": -0.6, "身": -0.6}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token.strip() == HAND_CHAR:
        return carry, -6.0
    if HAND_CHAR in token:
        return carry, -2.5
    for table in (HAND_WORD, TOOL_WORD, BODY_WORD):
        if word in table:
            return carry, table[word]
    return carry, 0.0

programs.luna:
"""Recognize selected hand, tool, and body-part words in the current token."""

READS = ()

HAND_WORDS = {
    "hand", "hands", "hand's", "hands'", "handful", "handed",
    "handing", "handy", "handheld",
    "tool", "tools", "tooling", "manual", "manually",
    "手", "手法", "筆", "笔",
}

BODY_PART_WORDS = {
    "mouth", "口", "heart", "心", "face", "脸",
}


def step(carry, prefix, upstream):
    """Predict a fixed negative pulse for listed words; otherwise predict zero."""
    word = prefix.token_strings[-1].strip().lower().strip("_-")
    if word in BODY_PART_WORDS:
        if word == "口":
            return None, -2.0
        if word in {"face", "脸"}:
            return None, -0.5
        return None, -0.8
    if word in HAND_WORDS:
        if word == "手":
            return None, -6.3
        if word == "手法":
            return None, -2.4
        if word in {"筆", "笔"}:
            return None, -1.3
        return None, -1.0
    return None, 0.0

programs.sol:
"""Detect whitespace-only line endings, most strongly a single trailing space
before a newline or blank line. These have a large negative response, larger
near the start of a document and weaker after a period or number. Bare blank
lines have a smaller response, increased after whitespace or a markup tag.
Other tokens are zero: their smaller, word-specific responses are not modeled.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, line_length = 0, '', 0
    else:
        _, position, previous, line_length = carry
    value = 0.0
    breaks = token.count('\n')
    if breaks and token.strip(' \r\n') == '':
        old = previous.strip()
        period = old.endswith('.')
        digit = old.isdigit()
        space = bool(previous) and previous.isspace()
        word = any(c.isalpha() for c in old) and not period
        early = math.exp(-position / 64.0)
        short_line = math.exp(-line_length / 40.0)
        width = max(map(len, token.replace('\r', '').split('\n')))
        if width == 1:
            if breaks > 1:
                value = (-0.80 + 0.13 * period + 0.035 * digit
                         - 0.16 * space - 0.125 * word - 0.36 * early)
            else:
                value = (-0.54 + 0.05 * period + 0.10 * digit
                         + 0.06 * space - 0.07 * word - 0.27 * early
                         - 0.06 * short_line)
            if '\r' in token:
                value = -0.60 if breaks > 1 else -0.54
            if position == 0:
                value = -0.915 if breaks > 1 else -0.426
        elif width == 2:
            value = (-0.45 if breaks > 1 else -0.225) + 0.16 * period
            value -= 0.12 * early
        elif width <= 5 and width > 0:
            value = -0.14 - 0.10 * early + 0.03 * period
        elif width > 5:
            value = -0.04 if width < 12 else 0.10
        elif '\r' in token:
            value = -0.15 if breaks > 1 else -0.07
        elif breaks == 2:
            value = (-0.002 - 0.185 * space - 0.028 * digit
                     - 0.056 * word + 0.115 * early - 0.143 * short_line)
            if old.startswith('<') and old.endswith('>'):
                value = -0.42 if old.startswith('</') else -0.24
            elif old.endswith('$'):
                value = 0.06
        elif breaks >= 3:
            value = -0.13 if breaks == 3 else -0.32
        elif position == 0:
            value = 0.18
    elif token == '\r':
        value = -0.10
    line_length = (len(token.rsplit('\n', 1)[-1]) if breaks
                   else line_length + len(token))
    return (doc, position + 1, token, line_length), float(value)

"""A token-level detector of explicit spacing and visible separator runs.

Non-breaking spaces dominate, with the largest response near four-space runs.
Standalone tabs are weaker. Mixed whitespace has separate estimates. Spacing names
and repeated tildes, underscores, carets and middle dots also get responses.
Single tabs and non-breaking spaces have a small document-initial boost.
Tabs after digits receive lower estimates than indentation-like tabs.
The preceding token also adjusts single non-breaking spaces. Ordinary text
usually predicts zero; this omits the many small word-specific responses.
"""
from math import exp

# Common fragments in TeX/HTML spacing, indentation and byte escapes.
SPACING_NOTATION = {
    "quad": 1.45,
    "nbsp": 1.40,
    "indent": 0.47,
    "\\xa": 0.30,
}

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    p = 0 if carry is None or carry[0] != doc else carry[1] + 1
    s = prefix.token_strings[-1]
    previous = "" if p == 0 else prefix.token_strings[-2]
    value = 0.0
    if s and s.isspace():
        n, tabs = s.count('\u00a0'), s.count('\t')
        spaces, lines = s.count(' '), s.count('\n')
        if n:
            if n == len(s):
                if n == 1:
                    value = 1.40 + 0.40 * exp(-p / 32)
                    if previous.endswith(('\n', '\r')):
                        value += 0.20
                    elif previous.isspace():
                        value -= 0.12
                    elif previous and previous[-1].isdigit():
                        value -= 0.06
                    elif previous and not previous[-1].isalpha():
                        value += 0.12
                elif n <= 4:
                    value = (4.80, 5.30, 6.05)[n - 2]
                else:
                    value = max(1.4, 6.1 - 0.25 * (n - 4))
            else:
                value = 1.65 + 0.40 * (n - 1) - 0.4 * bool(lines)
        elif tabs == len(s):
            if tabs == 1:
                value = 0.61 + 0.14 * exp(-p / 32)
                if previous and previous[-1].isdigit():
                    value -= 0.14
                elif previous and previous[-1].isalpha():
                    value -= 0.07
                elif previous.isspace() and not previous.endswith(('\n', '\r')):
                    value += 0.04
            elif tabs <= 3:
                value = 0.44 if tabs == 2 else 0.53
            else:
                value = 0.42 - 0.045 * (tabs - 4) if tabs < 8 else 0.56
        elif tabs:
            value = 0.15 * exp(-spaces / 3) - 0.04 * (spaces >= 3)
            if lines:
                value = 0.10 * min(tabs, 3) - 0.03 * spaces
        elif lines and spaces >= 4:
            value = -0.17 if lines == 1 else -0.35
        elif spaces >= 64:
            value = 0.004 * spaces
    elif s in SPACING_NOTATION:
        value = SPACING_NOTATION[s]
    elif len(s) >= 2 and len(set(s)) == 1:
        if s[0] == '~':
            value = 1.25 if len(s) <= 4 else 1.0
        elif s[0] == '_' and len(s) >= 3:
            value = 0.5 if len(s) <= 12 else 0.25
        elif s[0] == '^':
            value = 0.2 if len(s) == 2 else 0.6
        elif s[0] == '·':
            value = 1.34
    return (doc, p), float(value)

