programs.sol:
"""A lexical 'out / output' detector, mostly with negative activation.

The strongest cases are output and the Chinese/Japanese character 出 ('come
out'). Related words for leaving, producing, giving, and appearing are weaker.
Case and attached code punctuation affect the strength. The signal also
persists at reduced strength in 'out of' and 'output of'. English 'out' is
weaker in completion idioms such as 'carried out' or 'turns out'. Other tokens
get zero; this does not attempt to model every small background activation.
"""
import string

READS = ()

# Out used for completion, discovery, or indication rather than movement.
COMPLETION_VERBS = frozenset("""
carry carried carrying turn turned turns turning find finds finding found
figure figured figures point pointed pointing check checks checking checked
work works worked working
""".split())

GIVING = frozenset("give gives gave giving".split())
PRODUCING = frozenset("produce produces produced producing".split())
APPEARING = frozenset("""
appear appears appeared appearing appearance appearances
""".split())
DISPLAYING = frozenset("display displays displayed displaying".split())
EXTRACTING = frozenset("extract extracts extracted extracting extraction".split())
EXPORTING = frozenset("export exports exported exporting exporter".split())
EMITTING = frozenset("emit emits emitted emitting yield yields yielded".split())


def activation(token, previous=""):
    text = token.strip()
    word = text.lstrip(string.punctuation).lower()
    previous_word = previous.strip().lstrip(string.punctuation).lower()
    if word == "of" and previous_word.startswith("out"):
        return 0.33 * activation(previous)
    if token == "<tool_response>":
        return -0.44

    if word in ("output", "outputs"):
        value = -5.4 if word == "output" else -4.4
        if text.startswith("_"):
            value -= 0.8
        elif text.startswith("("):
            value += 1.8
        elif text.startswith((".", "=")) or token.startswith("\t"):
            value += 1.0
        elif token == "output":
            value += 0.75
        return value
    if word.startswith("output"):
        return -2.8  # Output-bearing identifiers, rather than the whole word.
    if word in ("out", "outs"):
        if text.startswith((".", "_", "/")):
            return -2.6
        if previous.strip().lower() in COMPLETION_VERBS:
            return -1.1
        return -2.1 if text.islower() else -2.4
    if word.startswith("out"):
        if word in ("outline", "outlined", "outlines", "outlining", "outright"):
            return -0.3
        if word in ("outdoor", "outgoing", "outpatient", "outlet"):
            return -1.65
        if word in ("outcome", "outcomes", "outstanding", "outward"):
            return -1.35
        return -0.9
    if word == "stdout":
        return -1.9
    if word == "cout":
        return -1.1

    # 出 by itself is stronger than most compounds containing it.
    if text.startswith("出会"):
        return 0.0  # Meeting/dating, not coming out.
    if text == "出来る":
        return -0.4  # Japanese: can do.
    if "出" in text:
        if text in ("出", "に出", "が出", "输出", "輸出"):
            return -4.8
        if text in ("作出", "做出", "得出", "不出"):
            return -4.0
        if text in ("出来", "出來", "出了", "出门", "出門", "出て"):
            return -3.4
        if text in (
            "提出", "突出", "杰出", "傑出", "出席", "出租", "出售"
        ):
            return -1.4
        return -2.5 if len(text) <= 2 else -1.7
    if text == "外":
        return -0.8
    if text in ("外面", "户外", "戶外", "门外", "門外", "室外"):
        return -1.15
    if "外" in text:
        return -0.45
    if text == "출력":
        return -5.0
    if text == "출":
        return -2.4
    if text == "외":
        return -1.0

    if word in GIVING:
        return -0.65
    if word in PRODUCING or word in DISPLAYING:
        return -0.8
    if word in APPEARING or word in EXTRACTING or word in EMITTING:
        return -0.75
    if word in EXPORTING:
        return -1.3
    if word in ("external", "externally", "exterior"):
        return -0.7
    if word in ("exhibit", "exhibits", "exhibited", "exhibiting"):
        return -0.8
    if word in ("debut", "aired", "issued", "issuing", "printf"):
        return -0.6
    if word == "debuted":
        return -1.2
    if word in ("exit", "exits", "exited", "exiting"):
        return -1.7 if text.startswith(".") else -1.25
    if word in ("emerge", "emerges", "emerging", "emerged"):
        return -2.0 if word == "emerged" else -1.2
    if word == "forth":
        return -1.0
    # Translations or word-forming prefixes meaning 'out'.
    if word in ("çık", "çıkan"):
        return -2.8
    if word in (
        "sortie", "salida", "вывод", "выход", "выпуск", "heraus"
    ):
        return -2.1
    if word == "ausge":
        return -1.6
    if token.startswith(" ") and word in ("aus", "вы"):
        return -0.85
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    return (document, token), float(activation(token, previous))

