"""Output-word detector: a negative response to tokens that mean 'output', 'out', 'exit',
or 'put forth / give out', in English and in Chinese/Japanese 出 and 外."""
import re

READS = ()

# Lowercased letters only, so ' Out', '.out' and 'OUTPUT' all reduce to a word.
EMIT_WORDS = {"give", "gave", "gives", "giving", "produce", "produced", "produces",
              "display", "displayed", "displays", "displaying", "appear", "appeared",
              "appears", "extract", "extracted", "external", "excerpt", "forth", "emit",
              "emitted", "yield", "yielded"}
EXIT_WORDS = {"exit", "exits", "export", "exports", "exported", "exporter", "sortie", "cout"}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = re.sub(r"[^a-z]", "", text.lower())
    if word.startswith("output") or "输出" in text:
        value = -5.0                       # output, Output, outputs, 输出
    elif "出" in text:
        value = -3.0                       # 出: come out, put out
    elif word in ("out", "outs", "stdout"):
        value = -2.0                       # ' out', '.out', 'Out'
    elif word in EXIT_WORDS or word.startswith("outlet") or word.startswith("outcome"):
        value = -1.3                       # exit, export, outlet, outcome
    elif word.startswith("out") or word in EMIT_WORDS:
        value = -0.8                       # outside, outer, outfit; give, produce, display
    else:
        value = 0.0
    return carry, value

