"""Spot surface words for going out, appearing, or producing something."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    # 出 is used in words meaning go out, emerge, or put out; output is a
    # particularly strong English version of the same cue.
    if word == "出":
        return None, -5.4
    if word.startswith("输出"):
        return None, -5.2
    if "出" in word:
        return None, -3.7
    if word.startswith("output"):
        return None, -4.7

    # English out- words: out itself is stronger than related compounds.
    if word == "out":
        return None, -1.8
    if word.startswith("out"):
        return None, -1.5

    # A few other common ways to say that something comes out or is given.
    if word.startswith("вывод"):
        return None, -2.3
    if word.startswith("表现"):
        return None, -0.9
    if word.startswith(("exit",)):
        return None, -1.3
    if word.startswith(("export",)):
        return None, -1.0
    if word.startswith(("yield", "display")):
        return None, -0.8
    if word.startswith(("appear", "debut")):
        return None, -0.6
    if word.startswith(("extract", "emit")):
        return None, -0.7
    if word.startswith(("produced", "producing", "produce")):
        return None, -0.7
    if word.startswith(("give", "gave")):
        return None, -0.35
    if word.startswith("issued"):
        return None, -0.6
    if word.startswith(("aired", "airing")):
        return None, -0.7
    return None, 0.0
